SELECT * FROM ( SELECT JHTT.ACPTDNPYNO, JHTT.APKIHONCD, JHTT.EDANO , JHTT.SHOPCD, JHTT.TOKUISAKICD, TKSM.TOKUISAKINMN1, TKSM.JIGYOSHOCD, JHTT.ACPTDD, JHTT.DLVRYYTIDD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYYTIRGRAYUSYOHNS, JHTT.DLVRYYTIRGRAMUSHOHNS, JHTT.DLVRYJISSEKIRGRAYUSYOHNS, JHTT.DLVRYJISSEKIRGRAMUSHOHNS, JHTT.DLVRYYTISRMYUSYOHNS, JHTT.DLVRYYTISRMMUSHOHNS, JHTT.DLVRYJISSEKISRMYUSYOHNS, JHTT.DLVRYJISSEKISRMMUSHOHNS, JHTT.DLVRYYTISONOTAYUSYOHNS, JHTT.DLVRYYTISONOTAMUSHOHNS, JHTT.DLVRYJISSEKISTYSHNS, JHTT.DLVRYJISSEKISTMSHNS, JHTT.DLVRYYTISEIHINMIZUURIKIN, JHTT.DLVRYJISSEKISHSUAKIN, JHTT.DLVRYYTISONOTAURIKIN, JHTT.DLVRYJISSEKISONOTAURIKIN, JHTT.DLVRYJISSEKIPRCSDD, JHTT.KYBTLN8RITTORUHNS, JHTT.KZBTLN8RITTORUHNS, JHTT.KYBTLN1N2RITTORUHNS, JHTT.KZBTLN1N2RITTORUHNS, SYKM1.MOJISETTEIATAI MOJISETTEIATAI1, SYKM2.MOJISETTEIATAI MOJISETTEIATAI2, TTSM1.TNSHAMEI TNSHAMEI1, TTSM2.TNSHAMEI TNSHAMEI2
FROM S04T001T JHTT LEFT OUTER JOIN S02M013T TKSM ON TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD LEFT OUTER JOIN S02M003T TTSM1 ON TTSM1.APKIHONCD = JHTT.ACPTTNSHAAPKIHONCD AND TTSM1.SHOPCD = JHTT.ACPTTNSHASHOPCD AND TTSM1.TNSHACD = JHTT.ACPTTNSHACD LEFT OUTER JOIN S02M003T TTSM2 ON TTSM2.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND TTSM2.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND TTSM2.TNSHACD = JHTT.DLVRYTNSHACD LEFT OUTER JOIN S02M006T SYKM1 ON SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '052' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = JHTT.ACPTKBN LEFT OUTER JOIN S02M006T SYKM2 ON SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '026' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = JHTT.DNPYSTS
WHERE JHTT.DNPYSTS IN ('01', '02' , '03' , '09' , '11' , '12' , '13' , '14', '19') AND JHTT.YUKOKBN = '1'
AND TKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
AND JHTT.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND JHTT.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD
AND JHTT.DLVRYKYOTENCD = #{dlvrykyotencd,jdbcType=VARCHAR}
AND JHTT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND TKSM.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND JHTT.INPTSYSTMYMD || JHTT.INPTSYSTMJIKAN BETWEEN #{inptsystmymd1,jdbcType=VARCHAR} || #{inptsystmjikan1,jdbcType=VARCHAR} || '00' AND #{inptsystmymd2,jdbcType=VARCHAR} || #{inptsystmjikan2,jdbcType=VARCHAR} || '00'
AND JHTT.DLVRYYTIDD BETWEEN #{dlvryytidd1,jdbcType=VARCHAR} AND #{dlvryytidd2,jdbcType=VARCHAR}
AND JHTT.DLVRYJISSEKIDD BETWEEN #{dlvrydd1,jdbcType=VARCHAR} AND #{dlvrydd2,jdbcType=VARCHAR}
AND JHTT.ACPTTNSHACD = #{acpttnshacd,jdbcType=VARCHAR}
AND JHTT.DLVRYTNSHACD = #{dlvrytnshacd,jdbcType=VARCHAR}
AND JHTT.DLVRYKBN = '1'
AND JHTT.DLVRYKBN = '3'
AND JHTT.DLVRYKBN = '2' AND JHTT.DLVRYCMPNYCD = #{dlvrycmpnycd,jdbcType=VARCHAR}
AND JHTT.DNPYSTS = #{dnpysts,jdbcType=VARCHAR}
AND JHTT.TORIHIKIKBN = #{torihikikbn,jdbcType=VARCHAR}
AND JHTT.ACPTKBN = #{acptkbn,jdbcType=VARCHAR}
AND JHTT.ACPTDNPYNO >= #{dnpyno1,jdbcType=VARCHAR}
AND JHTT.ACPTDNPYNO <= #{dnpyno2,jdbcType=VARCHAR}
AND JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND JHTT.DLVRYAREACD = #{dlvryareacd,jdbcType=VARCHAR}
ORDER BY JHTT.DLVRYYTIDD DESC, JHTT.ACPTDNPYNO DESC, JHTT.EDANO DESC )

SELECT JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.DNPYKBN, JHTT.ACPTKBN, JHTT.ACPTKBNSHS, JHTT.TOKUISAKICD, JHTT.ACPTDD, JHTT.ACPTTNSHAAPKIHONCD, JHTT.ACPTTNSHASHOPCD, JHTT.ACPTTNSHACD, JHTT.DLVRYYTIDD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYDD, JHTT.DLVRYKIBOJIKAN, JHTT.DLVRYKIBOJIKANKBN, JHTT.DLVRYKIBOJIKANSHRY, JHTT.FZAIOKIKANOFLG, JHTT.FZAIOKIJISSEKIFLG, JHTT.DLVRYTNSHACD, JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHTT.DLVRYAREACD, JHTT.DLVRYKBN, JHTT.DLVRYCMPNYCD, JHTT.AZUKARIBTLN1N2RITTORUHNS, JHTT.KYBTLN1N2RITTORUHNS, JHTT.KZBTLN1N2RITTORUHNS, JHTT.AZUKARIBTLN8RITTORUHNS, JHTT.KYBTLN8RITTORUHNS, JHTT.KZBTLN8RITTORUHNS, JHTT.PRNTMEMON1, JHTT.PRNTMEMON2, JHTT.PRNTMEMON3, JHTT.DLVRYJISSEKIPRCSDD, JHTT.DNPYSTS, JHTT.ACPTSTS, JHTT.DATSKSMOTOKBN, JHTT.DLVRYJISSEKIRGRAYUSYOHNS, JHTT.DLVRYJISSEKIRGRAMUSHOHNS, JHTT.DLVRYJISSEKISRMYUSYOHNS, JHTT.DLVRYJISSEKISRMMUSHOHNS, JHTT.DLVRYJISSEKISTYSHNS, JHTT.DLVRYJISSEKISTMSHNS, JHTT.DLVRYJISSEKISHSUAKIN, JHTT.DLVRYJISSEKISONOTAURIKIN, JHTT.ACPTKIN, JHTT.ACPTSHOHITAXKIN, JHTT.NOHINKIN, JHTT.NOHINSHOHITAXKIN, JHTT.YUKOKBN, JHTT.KSHNSYSTMYMD, JHTT.KSHNSYSTMJIKAN, JHTT.ACPTRCPTKEIROKBN, SKSM.KAISHUHOHOKBN, JHTT.ACPTTHDAIBIKIFLG, JHTT.ITAKUAITEAPKIHONCD, JHTT.ITAKUAITESHOPCD, JHTT.ITAKUAITEACPTDNPYNO, JHTT.ITAKUAITEEDANO, JHTT.URIDNPYNO, TKSM.SKYSAKICD, TKSM.JOTAISTS, TKSM.ACPTTEISHIFLG, TKSM.TOKUISAKIKBN, HKNM.DLVRYKYOTENNM, HTAM.DLVRYAREANM, (CASE WHEN HTAM.DLVRYSHUA = '1' THEN 'A' ELSE '' END || CASE WHEN HTAM.DLVRYSHUB = '1' THEN 'B' ELSE '' END || CASE WHEN HTAM.DLVRYSHUC = '1' THEN 'C' ELSE '' END || CASE WHEN HTAM.DLVRYSHUD = '1' THEN 'D' ELSE '' END || ' ' || CASE WHEN HTAM.SUNDDLVRYKANODD = '1' THEN '日' ELSE '' END || CASE WHEN HTAM.MONDDLVRYKANODD = '1' THEN '月' ELSE '' END || CASE WHEN HTAM.TUEDDLVRYKANODD = '1' THEN '火' ELSE '' END || CASE WHEN HTAM.WEDDDLVRYKANODD = '1' THEN '水' ELSE '' END || CASE WHEN HTAM.THEDDLVRYKANODD = '1' THEN '木' ELSE '' END || CASE WHEN HTAM.FRIDDLVRYKANODD = '1' THEN '金' ELSE '' END || CASE WHEN HTAM.SATDDLVRYKANODD = '1' THEN '土' ELSE '' END) DLYRYPTNNM, HTKM.DLVRYCMPNYNM, TTSM1.TNSHAMEI ACPTTNSHAMEI, TTSM2.TNSHAMEI DLVRYTNSHAMEI, SYKM1.MOJISETTEIATAI DNPYSTSMEI, SYKM2.MOJISETTEIATAI DATSKSMOTOKBNNM, SYKM3.MOJISETTEIATAI ACPTKBNNM, SYKM4.MOJISETTEIATAI ACPTKBNSHSNM, SYKM5.MOJISETTEIATAI NOHINSAKIJOHON1, SYKM6.MOJISETTEIATAI NOHINSAKIJOHON2, SYKM7.MOJISETTEIATAI DLVRYKIBOJIKANKBNNM FROM S04T001T JHTT LEFT OUTER JOIN S02M013T TKSM ON(TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD) LEFT OUTER JOIN S02M017T SKSM ON(SKSM.APKIHONCD = JHTT.APKIHONCD AND SKSM.SHOPCD = JHTT.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD) LEFT OUTER JOIN S02M031T HKNM ON(HKNM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HKNM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HKNM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD) LEFT OUTER JOIN S02M018T HTAM ON(HTAM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM.DLVRYAREACD = JHTT.DLVRYAREACD AND NVL(JHTT.DLVRYYTIDD, #{key.dlvryytidd,jdbcType=VARCHAR}) BETWEEN HTAM.TEKIYOSTRTDD AND HTAM.TEKIYOSHRYDD) LEFT OUTER JOIN S02M019T HTKM ON(HTKM.APKIHONCD = JHTT.APKIHONCD AND HTKM.SHOPCD = JHTT.SHOPCD AND HTKM.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD) LEFT OUTER JOIN S02M003T TTSM1 ON (TTSM1.APKIHONCD = JHTT.ACPTTNSHAAPKIHONCD AND TTSM1.SHOPCD = JHTT.ACPTTNSHASHOPCD AND TTSM1.TNSHACD = JHTT.ACPTTNSHACD) LEFT OUTER JOIN S02M003T TTSM2 ON (TTSM2.APKIHONCD = JHTT.APKIHONCD AND TTSM2.SHOPCD = JHTT.SHOPCD AND TTSM2.TNSHACD = JHTT.DLVRYTNSHACD) LEFT OUTER JOIN S02M006T SYKM1 ON (SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '026' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = JHTT.DNPYSTS) LEFT OUTER JOIN S02M006T SYKM2 ON (SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '093' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = JHTT.DATSKSMOTOKBN) LEFT OUTER JOIN S02M006T SYKM3 ON (SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '052' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = JHTT.ACPTKBN) LEFT OUTER JOIN S02M006T SYKM4 ON (SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.SETTEINO = '053' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEICD = JHTT.ACPTKBNSHS) LEFT OUTER JOIN S02M006T SYKM5 ON (SYKM5.APKIHONCD = '000' AND SYKM5.SHOPCD = '000' AND SYKM5.SETTEINO = '056' AND SYKM5.RCRDKBN = 'M' AND SYKM5.SETTEICD = TKSM.NOHINSAKIJOHON1) LEFT OUTER JOIN S02M006T SYKM6 ON (SYKM6.APKIHONCD = '000' AND SYKM6.SHOPCD = '000' AND SYKM6.SETTEINO = '057' AND SYKM6.RCRDKBN = 'M' AND SYKM6.SETTEICD = TKSM.NOHINSAKIJOHON2) LEFT OUTER JOIN S02M006T SYKM7 ON (SYKM7.APKIHONCD = '000' AND SYKM7.SHOPCD = '000' AND SYKM7.SETTEINO = '012' AND SYKM7.RCRDKBN = 'M' AND SYKM7.SETTEICD = JHTT.DLVRYKIBOJIKANKBN) WHERE JHTT.APKIHONCD = #{key.apkihoncd,jdbcType=VARCHAR} AND JHTT.SHOPCD = #{key.shopcd,jdbcType=VARCHAR}
AND JHTT.YUKOKBN = '1' AND JHTT.TOKUISAKICD = #{key.tokuisakicd,jdbcType=VARCHAR} AND JHTT.DNPYSTS = '01'
AND JHTT.ACPTDNPYNO = #{key.acptdnpyno,jdbcType=VARCHAR} AND JHTT.EDANO = #{key.edano,jdbcType=VARCHAR}
ORDER BY JHTT.ACPTDNPYNO DESC, JHTT.EDANO DESC

SELECT
   COUNT(ACPTDNPYNO) CNT
FROM
   S04T001T
WHERE
   APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
   AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
   AND SKSMOTOKANRIKBN = #{sksmotokanrikbn,jdbcType=VARCHAR}
   AND SKSMOTOKANRINO = #{sksmotokanrino,jdbcType=VARCHAR}

SELECT
   MAX ( ACPTDD ) SAISHUACPTDD
FROM S04T001T
WHERE
   APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
   AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
   AND TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
   AND YUKOKBN = '1'
 
   AND ACPTDNPYNO <> #{acptdnpyno,jdbcType=VARCHAR}

   AND DNPYSTS IN ('02', '03', '11', '12')

SELECT JHTT.DLVRYKANKATSUAPKIHONCD , JHTT.DLVRYKANKATSUSHOPCD , JHTT.DLVRYKYOTENCD , JHMT.SHNCD FOURTHKEY , SUM(JHMT.ACPTSURYO) ACPTSURYO , JHTT.DLVRYYTIDD FROM S04T002T JHMT INNER JOIN S04T001T JHTT ON(JHTT.APKIHONCD = JHMT.APKIHONCD AND JHTT.SHOPCD = JHMT.SHOPCD AND JHTT.ACPTDNPYNO = JHMT.ACPTDNPYNO AND JHTT.EDANO = JHMT.EDANO) WHERE JHTT.APKIHONCD = #{key.apkihoncd,jdbcType=VARCHAR} AND JHTT.SHOPCD = #{key.shopcd,jdbcType=VARCHAR}
AND JHTT.ACPTDNPYNO >= #{key.acptdennostart,jdbcType=VARCHAR} AND JHTT.ACPTDNPYNO <= #{key.acptdennoend,jdbcType=VARCHAR}
AND JHTT.EDANO = '0'
AND EXISTS ( SELECT 1 FROM S04W001T SJTW WHERE SJTW.APKIHONCD = JHTT.APKIHONCD AND SJTW.SHOPCD = JHTT.SHOPCD AND SJTW.ACPTDNPYNO = JHTT.ACPTDNPYNO AND SJTW.LOGINMONOAPKIHONCD = #{key.loginmonoapkihoncd,jdbcType=VARCHAR} AND SJTW.LOGINMONOSHOPCD = #{key.loginmonoshopcd,jdbcType=VARCHAR} AND SJTW.LOGINTANTOMONOCD = #{key.logintantomonocd,jdbcType=VARCHAR} )
AND JHTT.ITAKUAITEACPTDNPYNO IS NULL AND JHMT.MEISAIKBN = '0' AND JHMT.TANPINMEISAIFLG = '1'
AND JHMT.SHNCD IN (
#{regular}
#{slim}
)
GROUP BY JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD , JHMT.SHNCD, JHTT.DLVRYYTIDD
ORDER BY JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD , JHMT.SHNCD, JHTT.DLVRYYTIDD

SELECT MAX(T001.ACPTDD) AS MAX_ACPTDD 
