SELECT JHTT.APKIHONCD , JHTT.SHOPCD , JHTT.ACPTDNPYNO , JHTT.EDANO , JHTT.DLVRYYTIDD , JHTT.DLVRYKIBOJIKAN , JHTT.DLVRYYTIRGRAYUSYOHNS , JHTT.DLVRYYTIRGRAMUSHOHNS , JHTT.DLVRYYTISRMYUSYOHNS , JHTT.DLVRYYTISRMMUSHOHNS , JHTT.DLVRYYTISONOTAYUSYOHNS , JHTT.DLVRYYTISONOTAMUSHOHNS , TKSM.TOKUISAKICD || ' ' || TKSM.TOKUISAKINMN1 TNSHAMEI , SYKM1.MOJISETTEIATAI ACPTKBNNM , SYKM2.MOJISETTEIATAI ACPTKBNSHSNM , SYKM3.MOJISETTEIATAI DLVRYKIBOJIKANKBNNM FROM S04T001T JHTT LEFT OUTER JOIN S02M018T HTAM ON ( HTAM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM.DLVRYAREACD = JHTT.DLVRYAREACD AND JHTT.DLVRYYTIDD BETWEEN HTAM.TEKIYOSTRTDD AND HTAM.TEKIYOSHRYDD ) LEFT OUTER JOIN S02M006T SYKM1 ON ( SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO ='052' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = JHTT.ACPTKBN ) LEFT OUTER JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '053' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = JHTT.ACPTKBNSHS ) LEFT OUTER JOIN S02M006T SYKM3 ON ( SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '012' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = JHTT.DLVRYKIBOJIKANKBN ) LEFT OUTER JOIN S02M013T TKSM ON ( TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD ) LEFT OUTER JOIN S02M019T CMPN ON ( CMPN.APKIHONCD = JHTT.APKIHONCD AND CMPN.SHOPCD = JHTT.SHOPCD AND CMPN.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD ) LEFT OUTER JOIN S02M003T TTSM ON ( TTSM.APKIHONCD = JHTT.APKIHONCD AND TTSM.SHOPCD = JHTT.SHOPCD AND TTSM.TNSHACD = JHTT.DLVRYTNSHACD ) WHERE JHTT.YUKOKBN = '1' AND JHTT.DNPYSTS IN ('02' ,'03' ,'11') AND JHTT.DLVRYKANKATSUAPKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT.DLVRYKANKATSUSHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT.DLVRYTNSHACD = #{dlvrytnshacd,jdbcType=VARCHAR} AND JHTT.DLVRYYTIDD = #{dlvryytidd,jdbcType=VARCHAR}
AND JHTT.DLVRYKBN = '1'
AND JHTT.DLVRYKBN = '3'
AND JHTT.DLVRYCMPNYCD = #{dlvrycmpnycd,jdbcType=VARCHAR}
ORDER BY S05GETDLVRYTIME(JHTT.DLVRYKIBOJIKANKBN, JHTT.DLVRYKIBOJIKAN) , JHTT.DLVRYAREACD

SELECT * FROM ( SELECT SYKM1.MOJISETTEIATAI ACPTRCPTKBNMEI, JHTT1.ACPTDNPYNO ACPTDNPYNO, JHTT1.EDANO EDANO, JHTT1.APKIHONCD APKIHONCD, JHTT1.SHOPCD SHOPCD, JHTT1.TOKUISAKICD TOKUISAKICD, JHTT1.TOKUISAKINMN1 TOKUISAKINMN1, JHTT1.JIGYOSHOCD JIGYOSHOCD, JHTT1.ACPTDD ACPTDD, JHTT1.DLVRYYTIDD DLVRYYTIDD, NVL(JHTT1.DLVRYYTIRGRAYUSYOHNS,0) DLVRYYTIRGRAYUSYOHNS, NVL(JHTT1.DLVRYYTIRGRAMUSHOHNS,0) DLVRYYTIRGRAMUSHOHNS, NVL(JHTT1.DLVRYYTISRMYUSYOHNS,0) DLVRYYTISRMYUSYOHNS, NVL(JHTT1.DLVRYYTISRMMUSHOHNS,0) DLVRYYTISRMMUSHOHNS, NVL(JHTT1.DLVRYYTISONOTAYUSYOHNS,0) DLVRYYTISONOTAYUSYOHNS, NVL(JHTT1.DLVRYYTISONOTAMUSHOHNS,0) DLVRYYTISONOTAMUSHOHNS, NVL(JHTT1.DLVRYYTISEIHINMIZUURIKIN,0) DLVRYYTISEIHINMIZUURIKIN, NVL(JHTT1.DLVRYYTISONOTAURIKIN,0) DLVRYYTISONOTAURIKIN, TTSM.TNSHAMEI TNSHAMEI, SYKM2.MOJISETTEIATAI DNPYSTSNM FROM ( SELECT JHTT.ACPTKBN, JHTT.DNPYSTS, JHTT.ACPTTNSHACD, JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.TOKUISAKICD, TKSM.TOKUISAKINMN1, TKSM.JIGYOSHOCD, JHTT.ACPTDD, JHTT.DLVRYYTIDD, JHTT.DLVRYYTIRGRAYUSYOHNS, JHTT.DLVRYYTIRGRAMUSHOHNS, JHTT.DLVRYYTISRMYUSYOHNS, JHTT.DLVRYYTISRMMUSHOHNS, JHTT.DLVRYYTISONOTAYUSYOHNS, JHTT.DLVRYYTISONOTAMUSHOHNS, JHTT.DLVRYYTISEIHINMIZUURIKIN, JHTT.DLVRYYTISONOTAURIKIN, JHTT.ACPTTNSHAAPKIHONCD, JHTT.ACPTTNSHASHOPCD, JHTT.INPTSYSTMYMD, JHTT.INPTSYSTMJIKAN FROM S04T001T JHTT, S02M013T TKSM WHERE JHTT.APKIHONCD = TKSM.APKIHONCD AND JHTT.SHOPCD = TKSM.SHOPCD AND JHTT.TOKUISAKICD = TKSM.TOKUISAKICD AND JHTT.DNPYSTS IN ( #{dnpysts01,jdbcType=VARCHAR}, #{dnpysts02,jdbcType=VARCHAR}, #{dnpysts03,jdbcType=VARCHAR} ) AND JHTT.YUKOKBN = #{yukokbnnm,jdbcType=VARCHAR}
AND JHTT.INPTSYSTMYMD >= #{inptsystmymd1,jdbcType=VARCHAR}
AND JHTT.INPTSYSTMYMD <= #{inptsystmymd2,jdbcType=VARCHAR}
AND JHTT.INPTSYSTMYMD||JHTT.INPTSYSTMJIKAN >= #{inptsystmymd1,jdbcType=VARCHAR} || #{inptsystmjikan1,jdbcType=VARCHAR} || #{ssfrom,jdbcType=VARCHAR}
AND JHTT.INPTSYSTMYMD||JHTT.INPTSYSTMJIKAN <= #{inptsystmymd2,jdbcType=VARCHAR} || #{inptsystmjikan2,jdbcType=VARCHAR} || #{ssto,jdbcType=VARCHAR}
