AND JHMT_SUB.SHNCD NOT IN ( #{item.shncd,jdbcType=VARCHAR} ,
#{item.shncd,jdbcType=VARCHAR} ) AND JHMT_SUB.KEIJOKBN IN ('01', '02') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS HYUSYO , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD NOT IN ( #{item.shncd,jdbcType=VARCHAR} ,
#{item.shncd,jdbcType=VARCHAR} ) AND JHMT_SUB.KEIJOKBN NOT IN ('01', '02') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS HMUSYO FROM S04T001T JHTT_SUB INNER JOIN S04T002T JHMT_SUB ON ( JHMT_SUB.APKIHONCD = JHTT_SUB.APKIHONCD AND JHMT_SUB.SHOPCD = JHTT_SUB.SHOPCD AND JHMT_SUB.ACPTDNPYNO = JHTT_SUB.ACPTDNPYNO AND JHMT_SUB.EDANO = JHTT_SUB.EDANO ) WHERE JHTT_SUB.YUKOKBN = #{yukokbn,jdbcType=VARCHAR} AND JHTT_SUB.DNPYSTS = #{dnpysts,jdbcType=VARCHAR} AND JHTT_SUB.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT_SUB.DLVRYKANKATSUAPKIHONCD = #{dlvrykankatsuapkihoncd,jdbcType=VARCHAR} AND JHTT_SUB.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT_SUB.DLVRYKANKATSUSHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT_SUB.DLVRYKYOTENCD = #{dlvrykyotencd,jdbcType=VARCHAR}
