GROUP BY JHTT_SUB.APKIHONCD , JHTT_SUB.SHOPCD , JHTT_SUB.ACPTDNPYNO , JHTT_SUB.EDANO ) JHTT_SEIHINSUI INNER JOIN S04T001T JHTT ON ( JHTT.APKIHONCD = JHTT_SEIHINSUI.APKIHONCD AND JHTT.SHOPCD = JHTT_SEIHINSUI.SHOPCD AND JHTT.ACPTDNPYNO = JHTT_SEIHINSUI.ACPTDNPYNO AND JHTT.EDANO = JHTT_SEIHINSUI.EDANO ) INNER JOIN S02M013T TKSM ON ( TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD ) LEFT OUTER JOIN S02M006T SYKM012 ON ( SYKM012.APKIHONCD = '000' AND SYKM012.SHOPCD = '000' AND SYKM012.SETTEINO = '012' AND SYKM012.RCRDKBN = 'M' AND SYKM012.SETTEICD = JHTT.DLVRYKIBOJIKANKBN ) LEFT OUTER JOIN S02M006T SYKM052 ON ( SYKM052.APKIHONCD = '000' AND SYKM052.SHOPCD = '000' AND SYKM052.SETTEINO = '052' AND SYKM052.RCRDKBN = 'M' AND SYKM052.SETTEICD = JHTT.ACPTKBN ) LEFT OUTER JOIN S02M006T SYKM053 ON ( SYKM053.APKIHONCD = '000' AND SYKM053.SHOPCD = '000' AND SYKM053.SETTEINO = '053' AND SYKM053.RCRDKBN = 'M' AND SYKM053.SETTEICD = JHTT.ACPTKBNSHS ) LEFT OUTER JOIN S02M018T HTAM ON ( HTAM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM.DLVRYAREACD = JHTT.DLVRYAREACD AND HTAM.TEKIYOSTRTDD <= #{dlvryytidd1,jdbcType=VARCHAR} AND HTAM.TEKIYOSHRYDD >= #{dlvryytidd1,jdbcType=VARCHAR} ) LEFT OUTER JOIN S02M017T SKSM ON ( SKSM.APKIHONCD = TKSM.APKIHONCD AND SKSM.SHOPCD = TKSM.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD ) LEFT OUTER JOIN S02M019T HTKM ON ( HTKM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTKM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTKM.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD )
