SELECT MAIN.ITAKUAITEAPKIHONCD, MAIN.ITAKUAITESHOPCD, KIHON.APNM, SHOP.SHOPNM, NVL(SUM(DECODE(MAIN.DLVRYYTIDD, #{day1,jdbcType=VARCHAR}, MAIN.ACPTCNT, 0)), 0) AS ACPTCNT1, NVL(SUM(DECODE(MAIN.DLVRYYTIDD, #{day2,jdbcType=VARCHAR}, MAIN.ACPTCNT, 0)), 0) AS ACPTCNT2, NVL(SUM(DECODE(MAIN.DLVRYYTIDD, #{day3,jdbcType=VARCHAR}, MAIN.ACPTCNT, 0)), 0) AS ACPTCNT3, NVL(SUM(DECODE(MAIN.DLVRYYTIDD, #{day4,jdbcType=VARCHAR}, MAIN.ACPTCNT, 0)), 0) AS ACPTCNT4, NVL(SUM(DECODE(MAIN.DLVRYYTIDD, #{day5,jdbcType=VARCHAR}, MAIN.ACPTCNT, 0)), 0) AS ACPTCNT5, NVL(SUM(DECODE(MAIN.DLVRYYTIDD, #{day6,jdbcType=VARCHAR}, MAIN.ACPTCNT, 0)), 0) AS ACPTCNT6, NVL(SUM(DECODE(MAIN.DLVRYYTIDD, #{day7,jdbcType=VARCHAR}, MAIN.ACPTCNT, 0)), 0) AS ACPTCNT7, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day1,jdbcType=VARCHAR}, R.ACPTSURYO_R, 0)), 0) AS ACPTSURYO_R1, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day2,jdbcType=VARCHAR}, R.ACPTSURYO_R, 0)), 0) AS ACPTSURYO_R2, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day3,jdbcType=VARCHAR}, R.ACPTSURYO_R, 0)), 0) AS ACPTSURYO_R3, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day4,jdbcType=VARCHAR}, R.ACPTSURYO_R, 0)), 0) AS ACPTSURYO_R4, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day5,jdbcType=VARCHAR}, R.ACPTSURYO_R, 0)), 0) AS ACPTSURYO_R5, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day6,jdbcType=VARCHAR}, R.ACPTSURYO_R, 0)), 0) AS ACPTSURYO_R6, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day7,jdbcType=VARCHAR}, R.ACPTSURYO_R, 0)), 0) AS ACPTSURYO_R7, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day1,jdbcType=VARCHAR}, S.ACPTSURYO_S, 0)), 0) AS ACPTSURYO_S1, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day2,jdbcType=VARCHAR}, S.ACPTSURYO_S, 0)), 0) AS ACPTSURYO_S2, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day3,jdbcType=VARCHAR}, S.ACPTSURYO_S, 0)), 0) AS ACPTSURYO_S3, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day4,jdbcType=VARCHAR}, S.ACPTSURYO_S, 0)), 0) AS ACPTSURYO_S4, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day5,jdbcType=VARCHAR}, S.ACPTSURYO_S, 0)), 0) AS ACPTSURYO_S5, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day6,jdbcType=VARCHAR}, S.ACPTSURYO_S, 0)), 0) AS ACPTSURYO_S6, NVL(SUM(DECODE(R.DLVRYYTIDD, #{day7,jdbcType=VARCHAR}, S.ACPTSURYO_S, 0)), 0) AS ACPTSURYO_S7 FROM ( SELECT H.ITAKUAITEAPKIHONCD, H.ITAKUAITESHOPCD, H.DLVRYYTIDD, COUNT(*) ACPTCNT FROM S04T001T H WHERE H.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND H.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND H.DNPYSTS IN ('02','03','11') AND H.DATSKSMOTOKBN = '20' GROUP BY H.ITAKUAITEAPKIHONCD, H.ITAKUAITESHOPCD, H.DLVRYYTIDD ) MAIN LEFT JOIN ( SELECT H.ITAKUAITEAPKIHONCD, H.ITAKUAITESHOPCD, H.DLVRYYTIDD, SUM(D.ACPTSURYO) AS ACPTSURYO_R FROM S04T001T H JOIN S04T002T D ON H.APKIHONCD = D.APKIHONCD AND H.SHOPCD = D.SHOPCD AND H.ACPTDNPYNO = D.ACPTDNPYNO AND H.EDANO = D.EDANO WHERE D.SHNCD IN
#{item,jdbcType=VARCHAR}
AND H.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND H.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND H.DNPYSTS IN ('02','03','11') AND H.DATSKSMOTOKBN = '20' GROUP BY H.ITAKUAITEAPKIHONCD, H.ITAKUAITESHOPCD, H.DLVRYYTIDD ) R ON MAIN.ITAKUAITEAPKIHONCD = R.ITAKUAITEAPKIHONCD AND MAIN.ITAKUAITESHOPCD = R.ITAKUAITESHOPCD AND MAIN.DLVRYYTIDD = R.DLVRYYTIDD LEFT JOIN ( SELECT H.ITAKUAITEAPKIHONCD, H.ITAKUAITESHOPCD, H.DLVRYYTIDD, SUM(D.ACPTSURYO) AS ACPTSURYO_S FROM S04T001T H JOIN S04T002T D ON H.APKIHONCD = D.APKIHONCD AND H.SHOPCD = D.SHOPCD AND H.ACPTDNPYNO = D.ACPTDNPYNO AND H.EDANO = D.EDANO WHERE D.SHNCD IN
#{item,jdbcType=VARCHAR}
AND H.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND H.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND H.DNPYSTS IN ('02','03','11') AND H.DATSKSMOTOKBN = '20' GROUP BY H.ITAKUAITEAPKIHONCD, H.ITAKUAITESHOPCD, H.DLVRYYTIDD ) S ON MAIN.ITAKUAITEAPKIHONCD = S.ITAKUAITEAPKIHONCD AND MAIN.ITAKUAITESHOPCD = S.ITAKUAITESHOPCD AND MAIN.DLVRYYTIDD = S.DLVRYYTIDD LEFT JOIN S02M001T KIHON ON MAIN.ITAKUAITEAPKIHONCD = KIHON.APKIHONCD LEFT JOIN S02M046T SHOP ON MAIN.ITAKUAITEAPKIHONCD = SHOP.APKIHONCD AND MAIN.ITAKUAITESHOPCD = SHOP.SHOPCD GROUP BY MAIN.ITAKUAITEAPKIHONCD, MAIN.ITAKUAITESHOPCD, KIHON.APNM, SHOP.SHOPNM ORDER BY MAIN.ITAKUAITEAPKIHONCD, MAIN.ITAKUAITESHOPCD

