O_S, 0)), 0) AS ACPTSURYO_S7 FROM ( SELECT H.DLVRYKYOTENCD, H.DLVRYYTIDD, COUNT(*) ACPTCNT FROM S04T001T H WHERE H.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND H.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND H.DNPYSTS IN ('02', '03', '11') AND H.DATSKSMOTOKBN = '20' GROUP BY H.DLVRYKYOTENCD, H.DLVRYYTIDD ) MAIN LEFT JOIN ( SELECT H.DLVRYKYOTENCD, H.DLVRYYTIDD, SUM(D.ACPTSURYO) AS ACPTSURYO_R FROM S04T001T H JOIN S04T002T D ON H.APKIHONCD = D.APKIHONCD AND H.SHOPCD = D.SHOPCD AND H.ACPTDNPYNO = D.ACPTDNPYNO AND H.EDANO = D.EDANO WHERE D.SHNCD IN
