AND H.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND H.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND H.DNPYSTS IN ('02', '03', '11') AND H.DATSKSMOTOKBN = '20' GROUP BY H.DLVRYKYOTENCD, H.DLVRYYTIDD ) R ON MAIN.DLVRYKYOTENCD = R.DLVRYKYOTENCD AND MAIN.DLVRYYTIDD = R.DLVRYYTIDD LEFT JOIN ( SELECT H.DLVRYKYOTENCD, H.DLVRYYTIDD, SUM(D.ACPTSURYO) AS ACPTSURYO_S FROM S04T001T H JOIN S04T002T D ON H.APKIHONCD = D.APKIHONCD AND H.SHOPCD = D.SHOPCD AND H.ACPTDNPYNO = D.ACPTDNPYNO AND H.EDANO = D.EDANO WHERE D.SHNCD IN
#{item,jdbcType=VARCHAR}
AND H.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND H.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND H.DNPYSTS IN ('02', '03', '11') AND H.DATSKSMOTOKBN = '20' GROUP BY H.DLVRYKYOTENCD, H.DLVRYYTIDD ) S ON MAIN.DLVRYKYOTENCD = S.DLVRYKYOTENCD AND MAIN.DLVRYYTIDD = S.DLVRYYTIDD LEFT JOIN S02M031T KYOTEN ON KYOTEN.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND KYOTEN.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND MAIN.DLVRYKYOTENCD = KYOTEN.DLVRYKYOTENCD GROUP BY MAIN.DLVRYKYOTENCD, KYOTEN.DLVRYKYOTENNM ORDER BY MAIN.DLVRYKYOTENCD

SELECT
  COUNT(*)
FROM
  S04T001T JHTT,
  S04T002T JHMT,
  S02M013T TKSM
WHERE
  JHTT.APKIHONCD = TKSM.APKIHONCD
  AND JHTT.SHOPCD = TKSM.SHOPCD
  AND JHTT.TOKUISAKICD = TKSM.TOKUISAKICD
  AND JHTT.APKIHONCD = JHMT.APKIHONCD(+)
  AND JHTT.SHOPCD = JHMT.SHOPCD(+)
  AND JHTT.ACPTDNPYNO = JHMT.ACPTDNPYNO(+)
  AND JHTT.EDANO = JHMT.EDANO(+)
  AND JHMT.NYURYOKUMEISAIFLG(+) = #{nyuryokumeisaiflg,jdbcType=VARCHAR}
  AND JHTT.DNPYSTS  IN (
                       #{dnpysts01,jdbcType=VARCHAR},
                       #{dnpysts02,jdbcType=VARCHAR},
                       #{dnpysts03,jdbcType=VARCHAR}
  )
  AND JHTT.YUKOKBN  = #{yukokbnnm,jdbcType=VARCHAR}
  
  AND JHTT.INPTSYSTMYMD  >=  #{inptsystmymd1,jdbcType=VARCHAR}
  
  
  AND JHTT.INPTSYSTMYMD  <=  #{inptsystmymd2,jdbcType=VARCHAR}
  
  
  AND JHTT.INPTSYSTMYMD||JHTT.INPTSYSTMJIKAN  >=  #{inptsystmymd1,jdbcType=VARCHAR} || 
                                      #{inptsystmjikan1,jdbcType=VARCHAR} || #{ssfrom,jdbcType=VARCHAR}
  
  
  AND JHTT.INPTSYSTMYMD||JHTT.INPTSYSTMJIKAN  <=  #{inptsystmymd2,jdbcType=VARCHAR} || 
                                      #{inptsystmjikan2,jdbcType=VARCHAR} || #{ssto,jdbcType=VARCHAR}
  
  
  AND JHTT.DLVRYYTIDD  >=  #{dlvryytiddstr,jdbcType=VARCHAR}
  
  
  AND JHTT.DLVRYYTIDD  <=  #{dlvryytiddend,jdbcType=VARCHAR}
  
  
  AND JHTT.ACPTTNSHAAPKIHONCD = #{acpttnshaapkihoncd,jdbcType=VARCHAR}
  AND JHTT.ACPTTNSHASHOPCD = #{acpttnshashopcd,jdbcType=VARCHAR}
  AND JHTT.ACPTTNSHACD = #{acpttnshacd,jdbcType=VARCHAR}
  
  
  AND JHTT.DNPYSTS IN (#{dnpysts02,jdbcType=VARCHAR},#{dnpysts03,jdbcType=VARCHAR})
  
  
  AND JHTT.DNPYSTS = #{dnpysts,jdbcType=VARCHAR}
  
  
  AND JHTT.ACPTDNPYNO  >=  #{dnpynostr,jdbcType=VARCHAR}
  
  
  AND JHTT.ACPTDNPYNO  <=  #{dnpynoend,jdbcType=VARCHAR}
  
  
  AND JHTT.APKIHONCD = #{ttapkihoncd,jdbcType=VARCHAR}
  AND JHTT.SHOPCD = #{tokuisakishopcd,jdbcType=VARCHAR}
  AND JHTT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
  
  
  AND  JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  
  
  AND  JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
  
  
  AND TKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}

SELECT JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHMT.SHNCD FOURTHKEY, SUM(JHMT.ACPTSURYO) ACPTSURYO, JHTT.DLVRYYTIDD FROM S04T001T JHTT INNER JOIN S04T002T JHMT ON( JHTT.APKIHONCD = JHMT.APKIHONCD AND JHTT.SHOPCD = JHMT.SHOPCD AND JHTT.ACPTDNPYNO = JHMT.ACPTDNPYNO AND JHTT.EDANO = JHMT.EDANO ) WHERE JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT.ACPTDNPYNO >= #{acptdnpynostr,jdbcType=VARCHAR} AND JHTT.ACPTDNPYNO <= #{acptdnpynoend,jdbcType=VARCHAR} AND JHTT.EDANO = '0' AND JHTT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR} AND JHMT.MEISAIKBN = '0' AND JHMT.TANPINMEISAIFLG = '1' AND JHMT.SHNCD IN (
#{item,jdbcType=VARCHAR}
) GROUP BY JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHMT.SHNCD, JHTT.DLVRYYTIDD ORDER BY JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHMT.SHNCD, JHTT.DLVRYYTIDD

SELECT
    APKIHONCD,
    SHOPCD,
    ACPTDNPYNO,
    EDANO,
    KSHNSYSTMYMD,
    KSHNSYSTMJIKAN 
FROM S04T001T
WHERE APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
  AND ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR}
  AND EDANO = #{edano,jdbcType=VARCHAR}
FOR UPDATE

SELECT JHTT.ACPTSTS , JHTT.DLVRYKIBOJIKANKBN , JHTT.DLVRYKIBOJIKAN , JHTT.DLVRYKIBOJIKANSHRY , TKSM.JIGYOSHOCD , TKSM.YUBINNO , JHTT.PRNTMEMON1 , JHTT.PRNTMEMON2 , JHTT.PRNTMEMON3 , JHTT.AZUKARIBTLN1N2RITTORUHNS , JHTT.AZUKARIBTLN8RITTORUHNS , JHTT.KYBTLN1N2RITTORUHNS , JHTT.KYBTLN8RITTORUHNS , JHTT.DLVRYYTISONOTAURIKIN , JHTT.SINGLDNPYFLG , JHTT.ACPTTHDAIBIKIFLG , JHTT.FZAIOKIKANOFLG , JHTT.ACPTKBN , JHTT.DLVRYTNSHACD , JHTT.DLVRYAREACD , JHTT.DLVRYKBN , NVL(JHTT.DLVRYYTISEIHINMIZUURIKIN, 0) AS DLVRYYTISEIHINMIZUURIKIN , NVL(JHTT.DLVRYYTISONOTAURIKIN, 0) AS DLVRYYTISONOTAURIKIN , TKSM.ADRSN1 , TKSM.ADRSN2 , TKSM.RENRAKUSAKINON1 , TKSM.RENRAKUSAKINON2 , TKSM.TOKUISAKINMN1 , TKSM.CHIZUNO , TKSM.TOKUISAKIJOTAI , TKSM.TOKUISAKIKBN , TTSM_DLVRY.TNSHAMEI AS DLVRYTNSHAMEI , SHPM.SHOPNM , HTKM.DLVRYCMPNYCD , HTKM.DLVRYCMPNYNM , NVL(JHTT_SEIHINSUI.REGURI, 0) AS REGURI , NVL(JHTT_SEIHINSUI.REGSHIIN, 0) AS REGSHIIN , NVL(JHTT_SEIHINSUI.REGSONOTA, 0) AS REGSONOTA , NVL(JHTT_SEIHINSUI.SLMURI, 0) AS SLMURI , NVL(JHTT_SEIHINSUI.SLMSHIIN, 0) AS SLMSHIIN , NVL(JHTT_SEIHINSUI.SLMSONOTA, 0) AS SLMSONOTA , NVL(JHTT_SEIHINSUI.SNTURI, 0) AS SNTURI , NVL(JHTT_SEIHINSUI.SNTSHIIN, 0) AS SNTSHIIN , NVL(JHTT_SEIHINSUI.SNTSONOTA, 0) AS SNTSONOTA , NVL(JHTT_SEIHINSUI.ARS, 0) + NVL(JHTT_SEIHINSUI.ASS, 0) + NVL(JHTT_SEIHINSUI.AHS, 0) AS SRV_S , NVL(JHTT_SEIHINSUI.ARH, 0) + NVL(JHTT_SEIHINSUI.ASH, 0) + NVL(JHTT_SEIHINSUI.AHH, 0) AS SRV_H , NVL(JHTT_SEIHINSUI.HOKASHNSU, 0) AS HOKASHNSU , CASE WHEN JHTT.SINGLDNPYFLG = '1' THEN NVL(JHTT.ACPTKIN, 0) + NVL(JHTT.ACPTSHOHITAXKIN, 0) WHEN JHTT.ACPTTHDAIBIKIFLG = '1' THEN NVL(JHTT.ACPTKIN, 0) + NVL(JHTT.ACPTSHOHITAXKIN, 0) + NVL(JHTT_SEIHINSUI.MJMURGTAX, 0) + NVL(JHTT.ZNKKURIKOSHIKIN, 0) ELSE 0 END AS SHKNYTKIN
--消費税の算出(インボイス施行日前) , NVL(JHTT.ACPTSHOHITAXKIN, 0) AS ACPTSHOHITAXKIN
--消費税の算出(インボイス施行日後) --受注時代引フラグONの場合、「受注消費税金額＋未締売上消費税金額」を設定 --単体伝票締めフラグがONの場合、「受注消費税金額」を設定 , CASE WHEN JHTT.ACPTTHDAIBIKIFLG = '1' OR JHTT.SINGLDNPYFLG = '1' THEN NVL(JHTT.ACPTSHOHITAXKIN, 0) ELSE 0 END AS ACPTSHOHITAXKIN
, SYKM012.MOJISETTEIATAI AS DLVRYKIBOJIKANNM , SYKM056.MOJISETTEIATAI AS NOHINSAKIJOHON1 , SYKM057.MOJISETTEIATAI AS NOHINSAKIJOHON2 , SYKM051.MOJISETTEIATAI AS KAISHUHOHO , SYKM014.MOJISETTEIATAI AS TOKUISAKIJOTAINM , SKSM.KSIKKNTETSUZUKIFLG , DECODE(JHTT_SEIHINSUI.MEISAIKBN, '0', '0', '1') AS MEISAIKBN , JHTT_SEIHINSUI.ACPTDNPYNO , JHTT_SEIHINSUI.EDANO FROM ( SELECT JHTT_SUB.APKIHONCD , JHTT_SUB.SHOPCD , JHTT_SUB.ACPTDNPYNO , JHTT_SUB.EDANO , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN IN ('01', '02') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS REGURI --レギュラー、有料 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN = '05' AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS REGSHIIN --レギュラー、試飲 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN NOT IN ('01', '02', '05') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS REGSONOTA --レギュラー、その他 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN IN ('01', '02') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS SLMURI --スリム、有料 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN = '05' AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS SLMSHIIN --スリム、試飲 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN NOT IN ('01', '02', '05') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS SLMSONOTA --スリム、その他 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD NOT IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN IN ('01', '02') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS SNTURI --その他、有料 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD NOT IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN = '05' AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS SNTSHIIN --その他、試飲 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD NOT IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN NOT IN ('01', '02', '05') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS SNTSONOTA --その他、その他 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND NVL(JHMT_SUB.ACPTSURYO, 0) > 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS ARS , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND NVL(JHMT_SUB.ACPTSURYO, 0) > 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS ASS , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD NOT IN (
#{item,jdbcType=VARCHAR}
) AND NVL(JHMT_SUB.ACPTSURYO, 0) > 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS AHS , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND NVL(JHMT_SUB.ACPTSURYO, 0) < 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS ARH , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND NVL(JHMT_SUB.ACPTSURYO, 0) < 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS ASH , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD NOT IN (
#{item,jdbcType=VARCHAR}
) AND NVL(JHMT_SUB.ACPTSURYO, 0) < 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS AHH , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD <> #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.TANPINMEISAIFLG <> '0' OR JHMT_SUB.MEISAIKBN = '1' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS HOKASHNSU , SUM( CASE WHEN JHMT_SUB.MEISAIKBN = '1' THEN 1 ELSE 0 END ) AS MEISAIKBN , NVL( ( SELECT SUM( NVL(URGT_SUB.URIKIN, 0) + NVL(URGT_SUB.SHOHITAXKIN, 0) ) FROM S06T001T URGT_SUB WHERE JHTT_SUB.APKIHONCD = URGT_SUB.APKIHONCD AND JHTT_SUB.SHOPCD = URGT_SUB.SHOPCD AND JHTT_SUB.ACPTDNPYNO = URGT_SUB.ACPTDNPYNO AND JHTT_SUB.EDANO = URGT_SUB.EDANO AND URGT_SUB.ACPTDNPYNO <> URGT_SUB.URIDNPYNO AND URGT_SUB.SKYSHIMEDYDM IS NULL ) , 0 ) AS MJMURGTAX FROM S04T001T JHTT_SUB INNER JOIN S04T002T JHMT_SUB ON ( JHMT_SUB.APKIHONCD = JHTT_SUB.APKIHONCD AND JHMT_SUB.SHOPCD = JHTT_SUB.SHOPCD AND JHMT_SUB.ACPTDNPYNO = JHTT_SUB.ACPTDNPYNO AND JHMT_SUB.EDANO = JHTT_SUB.EDANO ) WHERE JHTT_SUB.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT_SUB.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT_SUB.ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR} AND JHTT_SUB.EDANO = #{edano,jdbcType=VARCHAR} GROUP BY JHTT_SUB.APKIHONCD , JHTT_SUB.SHOPCD , JHTT_SUB.ACPTDNPYNO , JHTT_SUB.EDANO ) JHTT_SEIHINSUI INNER JOIN S04T001T JHTT ON ( JHTT.APKIHONCD = JHTT_SEIHINSUI.APKIHONCD AND JHTT.SHOPCD = JHTT_SEIHINSUI.SHOPCD AND JHTT.ACPTDNPYNO = JHTT_SEIHINSUI.ACPTDNPYNO AND JHTT.EDANO = JHTT_SEIHINSUI.EDANO ) INNER JOIN S02M013T TKSM ON ( TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD ) LEFT OUTER JOIN S02M003T TTSM_DLVRY ON ( TTSM_DLVRY.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND TTSM_DLVRY.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND TTSM_DLVRY.TNSHACD = JHTT.DLVRYTNSHACD ) LEFT OUTER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = JHTT.APKIHONCD AND SHPM.SHOPCD = JHTT.SHOPCD ) LEFT OUTER JOIN S02M019T HTKM ON ( HTKM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTKM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTKM.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD ) LEFT OUTER JOIN S02M017T SKSM ON ( SKSM.APKIHONCD = TKSM.APKIHONCD AND SKSM.SHOPCD = TKSM.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD ) LEFT OUTER JOIN S02M006T SYKM012 ON ( SYKM012.APKIHONCD = '000' AND SYKM012.SHOPCD = '000' AND SYKM012.SETTEINO = '012' AND SYKM012.RCRDKBN = 'M' AND SYKM012.SETTEICD = JHTT.DLVRYKIBOJIKANKBN ) LEFT OUTER JOIN S02M006T SYKM051 ON ( SYKM051.APKIHONCD = '000' AND SYKM051.SHOPCD = '000' AND SYKM051.SETTEINO = '051' AND SYKM051.RCRDKBN = 'M' AND SYKM051.SETTEICD = SKSM.KAISHUHOHOKBN ) LEFT OUTER JOIN S02M006T SYKM056 ON ( SYKM056.APKIHONCD = '000' AND SYKM056.SHOPCD = '000' AND SYKM056.SETTEINO = '056' AND SYKM056.RCRDKBN = 'M' AND SYKM056.SETTEICD = TKSM.NOHINSAKIJOHON1 ) LEFT OUTER JOIN S02M006T SYKM057 ON ( SYKM057.APKIHONCD = '000' AND SYKM057.SHOPCD = '000' AND SYKM057.SETTEINO = '057' AND SYKM057.RCRDKBN = 'M' AND SYKM057.SETTEICD = TKSM.NOHINSAKIJOHON2 ) LEFT OUTER JOIN S02M006T SYKM014 ON ( SYKM014.APKIHONCD = '000' AND SYKM014.SHOPCD = '000' AND SYKM014.SETTEINO = '014' AND SYKM014.RCRDKBN = 'M' AND SYKM014.SETTEICD = TKSM.TOKUISAKIJOTAI ) ORDER BY JHTT_SEIHINSUI.ACPTDNPYNO , JHTT_SEIHINSUI.EDANO DESC

