HINSUI.ACPTKIN AS ACPTKIN , CASE WHEN JHTT.SINGLDNPYFLG = '1' THEN NVL(JHTT.ACPTKIN, 0) + NVL(JHTT.ACPTSHOHITAXKIN, 0) WHEN JHTT.ACPTTHDAIBIKIFLG = '1' THEN NVL(JHTT.ACPTKIN, 0) + NVL(JHTT.ACPTSHOHITAXKIN, 0) + NVL(JHTT_SEIHINSUI.MJMURGTAX, 0) + NVL (JHTT.ZNKKURIKOSHIKIN, 0) ELSE 0 END AS SHKNYTKIN , CASE WHEN JHTT.ACPTTHDAIBIKIFLG = '1' THEN NVL(JHTT_SEIHINSUI.MJMURGTAX, 0) ELSE 0 END AS MJMURGTAX , CASE WHEN JHTT_SEIHINSUI.MJMURGTAXCNT > 0 THEN 1 ELSE 0 END AS MJMURGTAXFLG
