, JHTT_SEIHINSUI.SUMACPTSHOHITAXKIN AS SUMACPTSHOHITAXKIN --受注消費税金額 , JHTT_SEIHINSUI.MEISAIBIKO AS MEISAIBIKO --明細備考 , JHTT_SEIHINSUI.DLVRYYTISEIHINMIZUURIKIN AS DLVRYYTISEIHINMIZUURIKIN --配達予定製品水売上金額 , JHTT_SEIHINSUI.DLVRYYTISONOTAURIKIN AS DLVRYYTISONOTAURIKIN --配達予定その他売上金額 , HHBM.HAIFUBUTSUNM AS HAIFUBUTSUNM , SKSM.KAISHUHOHOKBN AS KAISHUHOHOKBN , TKSM.SKYSAKICD AS SKYSAKICD , JHTT_SEIHINSUI.MEISAIKBN AS MEISAIKBN2 , SHMV.SHNNMKIRIKAEDD AS SHNNMKIRIKAEDD , SHMV.GENZSHNNM AS GENZSHNNM , SHMV.SHINSHNNM AS SHINSHNNM , SYKM009.MOJISETTEIATAI AS KEIJOKBNNM , JHTT_SEIHINSUI.TANPINMEISAIFLG AS TANPINMEISAIFLG --単品明細フラグ , JHTT.ACPTKBN AS ACPTKBN2 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '01' ) AS SARVERNM1 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '02' ) AS SARVERNM2 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '03' ) AS SARVERNM3 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '04' ) AS SARVERNM4 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '05' ) AS SARVERNM5 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '06' ) AS SARVERNM6 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '07' ) AS SARVERNM7 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '08' ) AS SARVERNM8 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '09' ) AS SARVERNM9 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '10' ) AS SARVERNM10 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '11' ) AS SARVERNM11 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '12' ) AS SARVERNM12 , ( SELECT MOJISETTEIATAI FROM S02M006T SYKM157_1 WHERE SYKM157_1.APKIHONCD = '000' AND SYKM157_1.SHOPCD = '000' AND SYKM157_1.SETTEINO = '157' AND SYKM157_1.RCRDKBN = 'M' AND SYKM157_1.SETTEICD = '13' ) AS SARVERNM13 , CASE WHEN JHTT_SEIHINSUI.LCTGRYCD = SYKM096.MOJISETTEIATAI THEN SYKM096.MOJISETTEIATAI END AS LCTGRYCD , CASE WHEN JHTT_SEIHINSUI.MCTGRYCD = SYKM134.MOJISETTEIATAI THEN SYKM134.MOJISETTEIATAI END AS MCTGRYCD , ( SELECT MOJISETTEIATAI FROM S02M006T WHERE APKIHONCD = '000' AND SHOPCD = '000' AND SETTEINO = '013' AND RCRDKBN = 'M' AND SETTEICD = SHMV.URITANI ) AS TANI , JHTT_SEIHINSUI.ACPTDNPYNO , JHTT_SEIHINSUI.EDANO FROM ( SELECT JHTT_SUB.APKIHONCD , JHTT_SUB.SHOPCD , JHTT_SUB.ACPTDNPYNO , JHTT_SUB.EDANO , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN IN ('01', '02') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS REGURI --レギュラー、有料 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN = '05' AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS REGSHIIN --レギュラー、試飲 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
#{item,jdbcType=VARCHAR}
) AND JHMT_SUB.KEIJOKBN NOT IN ('01', '02', '05') AND JHMT_SUB.TANPINMEISAIFLG <> '0' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS REGSONOTA --レギュラー、その他 , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD IN (
