) AND NVL(JHMT_SUB.ACPTSURYO, 0) < 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS ASH , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD = #{lctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.MCTGRYCD = #{mctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.SHNCD NOT IN (
#{item,jdbcType=VARCHAR}
) AND NVL(JHMT_SUB.ACPTSURYO, 0) < 0 ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS AHH , SUM( CASE WHEN ( JHMT_SUB.LCTGRYCD <> #{seihinsuilctgrycd,jdbcType=VARCHAR} AND JHMT_SUB.TANPINMEISAIFLG <> '0' OR JHMT_SUB.MEISAIKBN = '1' ) THEN NVL(JHMT_SUB.ACPTSURYO, 0) ELSE 0 END ) AS HOKASHNSU , SUM( CASE WHEN JHMT_SUB.MEISAIKBN = '1' THEN 1 ELSE 0 END ) AS MEISAIKBN , JHMT_SUB.KEIJOKBN , JHMT_SUB.HAIFUBUTSUCD , JHMT_SUB.SHNCD , JHMT_SUB.TANPINMEISAIFLG , JHMT_SUB.ACPTSURYO , SUM( CASE WHEN JHMT_SUB.ACPTSURYO > 0 THEN ACPTSURYO END ) AS ACPTSURYO2 , SUM( CASE WHEN JHMT_SUB.ACPTSURYO < 0 THEN ACPTSURYO END ) AS ACPTSURYO3 , JHMT_SUB.ACPTUNT AS ACPTUNT , SUM(JHMT_SUB.ACPTKIN) AS ACPTKIN --受注金額 , SUM(JHMT_SUB.ACPTSHOHITAXKIN) AS ACPTSHOHITAXKIN --受注消費税金額 , MAX(JHTT_SUB.ACPTSHOHITAXKIN) AS SUMACPTSHOHITAXKIN --受注消費税金額 , JHMT_SUB.MEISAIBIKO AS MEISAIBIKO --明細備考 , SUM(JHTT_SUB.DLVRYYTISEIHINMIZUURIKIN) AS DLVRYYTISEIHINMIZUURIKIN --配達予定製品水売上金額 , SUM(JHTT_SUB.DLVRYYTISONOTAURIKIN) AS DLVRYYTISONOTAURIKIN --配達予定その他売上金額 , JHMT_SUB.LCTGRYCD AS LCTGRYCD , JHMT_SUB.MCTGRYCD AS MCTGRYCD , JHMT_SUB.ACPTDNPYMEISAINO AS ACPTDNPYMEISAINO --受注伝票明細番号 , JHMT_SUB.ACPTDNPYMEISAIEDANO AS ACPTDNPYMEISAIEDANO --受注伝票明細枝番号 , NVL( ( SELECT SUM( NVL(URGT_SUB.URIKIN, 0) + NVL(URGT_SUB.SHOHITAXKIN, 0) ) FROM S06T001T URGT_SUB WHERE JHTT_SUB.APKIHONCD = URGT_SUB.APKIHONCD AND JHTT_SUB.SHOPCD = URGT_SUB.SHOPCD AND JHTT_SUB.ACPTDNPYNO = URGT_SUB.ACPTDNPYNO AND JHTT_SUB.EDANO = URGT_SUB.EDANO AND URGT_SUB.ACPTDNPYNO <> URGT_SUB.URIDNPYNO AND URGT_SUB.SKYSHIMEDYDM IS NULL ) , 0 ) AS MJMURGTAX , NVL( ( SELECT COUNT(1) FROM S06T001T URGT_SUB WHERE JHTT_SUB.APKIHONCD = URGT_SUB.APKIHONCD AND JHTT_SUB.SHOPCD = URGT_SUB.SHOPCD AND JHTT_SUB.ACPTDNPYNO = URGT_SUB.ACPTDNPYNO AND JHTT_SUB.EDANO = URGT_SUB.EDANO AND URGT_SUB.ACPTDNPYNO <> URGT_SUB.URIDNPYNO AND URGT_SUB.SKYSHIMEDYDM IS NULL ) , 0 ) AS MJMURGTAXCNT FROM S04T001T JHTT_SUB INNER JOIN S04T002T JHMT_SUB ON ( JHMT_SUB.APKIHONCD = JHTT_SUB.APKIHONCD AND JHMT_SUB.SHOPCD = JHTT_SUB.SHOPCD AND JHMT_SUB.ACPTDNPYNO = JHTT_SUB.ACPTDNPYNO AND JHMT_SUB.EDANO = JHTT_SUB.EDANO ) WHERE JHTT_SUB.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT_SUB.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT_SUB.ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR} AND JHTT_SUB.EDANO = #{edano,jdbcType=VARCHAR} AND JHMT_SUB.TANPINMEISAIFLG = '1' AND JHMT_SUB.MEISAIKBN <> '3' GROUP BY JHTT_SUB.APKIHONCD , JHTT_SUB.SHOPCD , JHTT_SUB.ACPTDNPYNO , JHTT_SUB.EDANO , JHMT_SUB.KEIJOKBN , JHMT_SUB.HAIFUBUTSUCD , JHMT_SUB.SHNCD , JHMT_SUB.ACPTUNT , JHMT_SUB.MEISAIBIKO , JHMT_SUB.TANPINMEISAIFLG , JHMT_SUB.LCTGRYCD , JHMT_SUB.MCTGRYCD , JHMT_SUB.ACPTSURYO , JHMT_SUB.ACPTDNPYMEISAINO , JHMT_SUB.ACPTDNPYMEISAIEDANO ) JHTT_SEIHINSUI INNER JOIN S04T001T JHTT ON ( JHTT.APKIHONCD = JHTT_SEIHINSUI.APKIHONCD AND JHTT.SHOPCD = JHTT_SEIHINSUI.SHOPCD AND JHTT.ACPTDNPYNO = JHTT_SEIHINSUI.ACPTDNPYNO AND JHTT.EDANO = JHTT_SEIHINSUI.EDANO ) INNER JOIN S02M013T TKSM ON ( TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD ) LEFT OUTER JOIN S02M003T TTSM_DLVRY ON ( TTSM_DLVRY.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND TTSM_DLVRY.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND TTSM_DLVRY.TNSHACD = JHTT.DLVRYTNSHACD ) LEFT OUTER JOIN S02M046T SHPM ON ( SHPM.APKIHONCD = JHTT.APKIHONCD AND SHPM.SHOPCD = JHTT.SHOPCD ) LEFT OUTER JOIN S02M019T HTKM ON ( HTKM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTKM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTKM.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD ) LEFT OUTER JOIN S02M017T SKSM ON ( SKSM.APKIHONCD = TKSM.APKIHONCD AND SKSM.SHOPCD = TKSM.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD ) LEFT OUTER JOIN S02M006T SYKM012 ON ( SYKM012.APKIHONCD = '000' AND SYKM012.SHOPCD = '000' AND SYKM012.SETTEINO = '012' AND SYKM012.RCRDKBN = 'M' AND SYKM012.SETTEICD = JHTT.DLVRYKIBOJIKANKBN ) LEFT OUTER JOIN S02M006T SYKM051 ON ( SYKM051.APKIHONCD = '000' AND SYKM051.SHOPCD = '000' AND SYKM051.SETTEINO = '051' AND SYKM051.RCRDKBN = 'M' AND SYKM051.SETTEICD = SKSM.KAISHUHOHOKBN ) LEFT OUTER JOIN S02M006T SYKM056 ON ( SYKM056.APKIHONCD = '000' AND SYKM056.SHOPCD = '000' AND SYKM056.SETTEINO = '056' AND SYKM056.RCRDKBN = 'M' AND SYKM056.SETTEICD = TKSM.NOHINSAKIJOHON1 ) LEFT OUTER JOIN S02M006T SYKM057 ON ( SYKM057.APKIHONCD = '000' AND SYKM057.SHOPCD = '000' AND SYKM057.SETTEINO = '057' AND SYKM057.RCRDKBN = 'M' AND SYKM057.SETTEICD = TKSM.NOHINSAKIJOHON2 ) LEFT OUTER JOIN S02M006T SYKM014 ON ( SYKM014.APKIHONCD = '000' AND SYKM014.SHOPCD = '000' AND SYKM014.SETTEINO = '014' AND SYKM014.RCRDKBN = 'M' AND SYKM014.SETTEICD = TKSM.TOKUISAKIJOTAI ) LEFT OUTER JOIN S02M006T SYKM009 ON ( SYKM009.APKIHONCD = '000' AND SYKM009.SHOPCD = '000' AND SYKM009.SETTEINO = '009' AND SYKM009.RCRDKBN = 'M' AND SYKM009.SETTEICD = JHTT_SEIHINSUI.KEIJOKBN ) LEFT OUTER JOIN S02M006T SYKM096 ON ( SYKM096.APKIHONCD = '000' AND SYKM096.SHOPCD = '000' AND SYKM096.SETTEINO = '096' AND SYKM096.RCRDKBN = 'M' AND SYKM096.SETTEICD = '4' ) LEFT OUTER JOIN S02M006T SYKM134 ON ( SYKM134.APKIHONCD = '000' AND SYKM134.SHOPCD = '000' AND SYKM134.SETTEINO = '134' AND SYKM134.RCRDKBN = 'M' AND SYKM134.SETTEICD = '41' ) LEFT OUTER JOIN S02M035T HHBM ON ( JHTT_SEIHINSUI.APKIHONCD = HHBM.APKIHONCD AND JHTT_SEIHINSUI.SHOPCD = HHBM.SHOPCD AND JHTT_SEIHINSUI.HAIFUBUTSUCD = HHBM.HAIFUBUTSUCD ) LEFT OUTER JOIN S02V001T SHMV ON ( SHMV.APKIHONCD = JHTT_SEIHINSUI.APKIHONCD AND SHMV.SHOPCD = JHTT_SEIHINSUI.SHOPCD AND SHMV.SHNCD = JHTT_SEIHINSUI.SHNCD ) ORDER BY JHTT_SEIHINSUI.ACPTDNPYMEISAINO , JHTT_SEIHINSUI.ACPTDNPYMEISAIEDANO

SELECT JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, (SELECT SHPM1.SHOPNM FROM S02M046T SHPM1 WHERE SHPM1.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND SHPM1.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD ) AS SHOPNM1, JHTT.DLVRYKYOTENCD, (SELECT HKNM.DLVRYKYOTENNM FROM S02M031T HKNM WHERE HKNM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HKNM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HKNM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD ) AS DLVRYKYOTENNM, (SELECT TTSM1.TNSHAMEI FROM S02M003T TTSM1 WHERE TTSM1.APKIHONCD = #{loginapkihoncd, jdbcType=VARCHAR} AND TTSM1.SHOPCD = #{loginshopcd, jdbcType=VARCHAR} AND TTSM1.TNSHACD = #{logintnshacd, jdbcType=VARCHAR} ) AS TNSHAMEI1, JHTT.DLVRYJISSEKIDD,
(SELECT TTSM2.TNSHAMEI FROM S02M003T TTSM2 WHERE TTSM2.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND TTSM2.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND TTSM2.TNSHACD = JHTT.DLVRYTNSHACD ) AS TNSHAMEI2, (SELECT HTKM.DLVRYCMPNYNM FROM S02M019T HTKM WHERE HTKM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTKM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTKM.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD ) AS DLVRYCMPNYNM,
(SELECT HTAM1.DLVRYAREANM FROM S02M018T HTAM1 WHERE HTAM1.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM1.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM1.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM1.DLVRYAREACD = JHTT.DLVRYAREACD AND HTAM1.TEKIYOSTRTDD(+) <= #{unyodate, jdbcType=VARCHAR} AND HTAM1.TEKIYOSHRYDD(+) >= #{unyodate, jdbcType=VARCHAR} ) AS DLVRYAREANM1,
(SELECT SHPM2.SHOPNM FROM S02M046T SHPM2 WHERE SHPM2.APKIHONCD = JHTT.APKIHONCD AND SHPM2.SHOPCD = JHTT.SHOPCD ) AS SHOPNM2,
(SELECT SYKM1.MOJISETTEIATAI FROM S02M006T SYKM1 WHERE SYKM1.APKIHONCD = #{apkihoncd000, jdbcType=VARCHAR} AND SYKM1.SHOPCD = #{shopcd000, jdbcType=VARCHAR} AND SYKM1.RCRDKBN = #{recordkbn, jdbcType=VARCHAR} AND SYKM1.SETTEINO = #{setteino026, jdbcType=VARCHAR} AND SYKM1.SETTEICD = JHTT.DLVRYSTS ) AS MOJISETTEIATAI1, JHTT.TOKUISAKICD, JHTT.APKIHONCD, JHTT.SHOPCD, (SELECT TKSM.TOKUISAKINMN1 FROM S02M013T TKSM WHERE TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD ) AS TOKUISAKINMN1, JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.FZAIOKIKANOFLG, (SELECT HTAM2.DLVRYAREANM FROM S02M018T HTAM2 WHERE JHTT.DLVRYKANKATSUAPKIHONCD = HTAM2.APKIHONCD AND JHTT.DLVRYKANKATSUSHOPCD = HTAM2.SHOPCD AND JHTT.DLVRYKYOTENCD = HTAM2.DLVRYKYOTENCD AND JHTT.DLVRYAREACD = HTAM2.DLVRYAREACD AND HTAM2.TEKIYOSTRTDD <= #{unyodate, jdbcType=VARCHAR} AND HTAM2.TEKIYOSHRYDD >= #{unyodate, jdbcType=VARCHAR} ) AS DLVRYAREANM2, (SELECT SYKM2.MOJISETTEIATAI FROM S02M006T SYKM2 WHERE SYKM2.APKIHONCD = #{apkihoncd000, jdbcType=VARCHAR} AND SYKM2.SHOPCD = #{shopcd000, jdbcType=VARCHAR} AND SYKM2.RCRDKBN = #{recordkbn, jdbcType=VARCHAR} AND SYKM2.SETTEINO = #{setteino052, jdbcType=VARCHAR} AND SYKM2.SETTEICD = JHTT.ACPTKBN ) AS MOJISETTEIATAI2, (SELECT SYKM3.MOJISETTEIATAI FROM S02M006T SYKM3 WHERE SYKM3.APKIHONCD = #{apkihoncd000, jdbcType=VARCHAR} AND SYKM3.SHOPCD = #{shopcd000, jdbcType=VARCHAR} AND SYKM3.RCRDKBN = #{recordkbn, jdbcType=VARCHAR} AND SYKM3.SETTEINO = #{setteino053, jdbcType=VARCHAR} AND SYKM3.SETTEICD = JHTT.ACPTKBNSHS ) AS MOJISETTEIATAI3, JHTT.DLVRYJISSEKIRGRAYUSYOHNS, JHTT.DLVRYJISSEKIRGRAMUSHOHNS, JHTT.DLVRYJISSEKISRMYUSYOHNS, JHTT.DLVRYJISSEKISRMMUSHOHNS, JHTT.DLVRYJISSEKISTYSHNS, JHTT.DLVRYJISSEKISTMSHNS, JHTT.KYBTLN1N2RITTORUHNS, JHTT.KZBTLN1N2RITTORUHNS, JHTT.KYBTLN8RITTORUHNS, JHTT.KZBTLN8RITTORUHNS, JHTT.DLVRYJISSEKISHSUAKIN, JHTT.DLVRYJISSEKISONOTAURIKIN, JHTT.KURERURITTORUSTUP, JHTT.KURERURITTORUHIKIAGE, JHTT.KURERUESUSTUP, JHTT.KURERUESUHIKIAGE, JHTT.SONOTASTUP, JHTT.SONOTAHIKIAGE, JHTT.DLVRYSTS ,NVL(JHTT_SEIHINSUI.SHNCD,0) AS SHNCD ,NVL(JHTT_SEIHINSUI.ACPTSURYO, 0) AS ACPTSURYO ,CASE WHEN JHTT_SEIHINSUI.LCTGRYCD = SYKM096.MOJISETTEIATAI THEN SYKM096.MOJISETTEIATAI END AS LCTGRYCD ,CASE WHEN JHTT_SEIHINSUI.MCTGRYCD = SYKM134.MOJISETTEIATAI THEN SYKM134.MOJISETTEIATAI END AS MCTGRYCD ,CASE WHEN SHPM0.INVOICSHIKOYMD > JHTT.DLVRYDD THEN NVL(JHTT.NOHINSHOHITAXKIN, 0) WHEN (SHPM0.INVOICSHIKOYMD <= JHTT.DLVRYDD) AND (JHTT.ACPTTHDAIBIKIFLG = '1' OR JHTT.SINGLDNPYFLG = '1') THEN NVL(JHTT.NOHINSHOHITAXKIN, 0) ELSE 0 END NOHINSHOHITAXKIN ,CASE WHEN SHPM0.INVOICSHIKOYMD > JHTT.DLVRYDD THEN NVL(JHTT.NOHINKEIGENTAXKIN, 0) WHEN (SHPM0.INVOICSHIKOYMD <= JHTT.DLVRYDD) AND (JHTT.ACPTTHDAIBIKIFLG = '1' OR JHTT.SINGLDNPYFLG = '1') THEN NVL(JHTT.NOHINKEIGENTAXKIN, 0) ELSE 0 END NOHINKEIGENTAXKIN ,CASE WHEN SHPM0.INVOICSHIKOYMD > JHTT.DLVRYDD THEN NVL(JHTT.NOHINIPPANTAXKIN, 0) WHEN (SHPM0.INVOICSHIKOYMD <= JHTT.DLVRYDD) AND (JHTT.ACPTTHDAIBIKIFLG = '1' OR JHTT.SINGLDNPYFLG = '1') THEN NVL(JHTT.NOHINIPPANTAXKIN, 0) ELSE 0 END NOHINIPPANTAXKIN FROM S04T001T JHTT INNER JOIN S02M046T SHPM0 ON (SHPM0.APKIHONCD = JHTT.APKIHONCD AND SHPM0.SHOPCD = JHTT.SHOPCD ) LEFT OUTER JOIN (SELECT JHTT_SUB.APKIHONCD ,JHTT_SUB.SHOPCD ,JHTT_SUB.ACPTDNPYNO ,JHTT_SUB.EDANO ,JHMT_SUB.SHNCD ,SUM(NOHINSURYO) AS ACPTSURYO ,SUM(CASE WHEN JHMT_SUB.NOHINSURYO > 0 THEN NOHINSURYO ELSE 0 END) AS ACPTSURYO2 ,SUM (CASE WHEN JHMT_SUB.NOHINSURYO < 0 THEN NOHINSURYO ELSE 0 END) AS ACPTSURYO3 ,JHMT_SUB.LCTGRYCD AS LCTGRYCD ,JHMT_SUB.MCTGRYCD AS MCTGRYCD ,JHMT_SUB.ACPTDNPYMEISAINO AS ACPTDNPYMEISAINO ,JHMT_SUB.ACPTDNPYMEISAIEDANO AS ACPTDNPYMEISAIEDANO FROM S04T001T JHTT_SUB INNER JOIN S04T002T JHMT_SUB ON (JHMT_SUB.APKIHONCD = JHTT_SUB.APKIHONCD AND JHMT_SUB.SHOPCD = JHTT_SUB.SHOPCD AND JHMT_SUB.ACPTDNPYNO = JHTT_SUB.ACPTDNPYNO AND JHMT_SUB.EDANO = JHTT_SUB.EDANO ) WHERE JHTT_SUB.APKIHONCD = #{apkihoncd, jdbcType=VARCHAR} AND JHTT_SUB.SHOPCD = #{shopcd, jdbcType=VARCHAR}
AND JHTT_SUB.APKIHONCD = JHTT_SUB.DLVRYKANKATSUAPKIHONCD AND JHTT_SUB.SHOPCD = JHTT_SUB.DLVRYKANKATSUSHOPCD
AND JHTT_SUB.DLVRYKYOTENCD = #{dlvrykyotencd, jdbcType=VARCHAR}
AND JHTT_SUB.APKIHONCD || JHTT_SUB.SHOPCD != JHTT_SUB.DLVRYKANKATSUAPKIHONCD || JHTT_SUB.DLVRYKANKATSUSHOPCD
AND JHTT_SUB.DLVRYJISSEKIPRCSDD IS NOT NULL AND JHTT_SUB.YUKOKBN = #{yukokbn, jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYTNSHACD = #{dlvrytnshacd, jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYKBN = #{dlvrykbn, jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYCMPNYCD = #{dlvrykaisyacd, jdbcType=VARCHAR}
AND JHTT_SUB.TOKUISAKICD = #{tokuisakicd, jdbcType=VARCHAR}
AND JHTT_SUB.ACPTDNPYNO >= #{dnpynostr, jdbcType=VARCHAR}
AND JHTT_SUB.ACPTDNPYNO <= #{dnpynoend, jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYAREACD IN
#{item,jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYJISSEKIDD = #{dlvrydd, jdbcType=VARCHAR}
GROUP BY JHTT_SUB.APKIHONCD ,JHTT_SUB.SHOPCD ,JHTT_SUB.ACPTDNPYNO ,JHTT_SUB.EDANO ,JHMT_SUB.SHNCD ,JHMT_SUB.LCTGRYCD ,JHMT_SUB.MCTGRYCD ,JHMT_SUB.ACPTDNPYMEISAINO ,JHMT_SUB.ACPTDNPYMEISAIEDANO ) JHTT_SEIHINSUI ON (JHTT.APKIHONCD = JHTT_SEIHINSUI.APKIHONCD AND JHTT.SHOPCD = JHTT_SEIHINSUI.SHOPCD AND JHTT.ACPTDNPYNO = JHTT_SEIHINSUI.ACPTDNPYNO AND JHTT.EDANO = JHTT_SEIHINSUI.EDANO ) LEFT OUTER JOIN S02M006T SYKM096 ON (SYKM096.APKIHONCD = #{apkihoncd000, jdbcType=VARCHAR} AND SYKM096.SHOPCD = #{shopcd000, jdbcType=VARCHAR} AND SYKM096.SETTEINO = #{setteino096, jdbcType=VARCHAR} AND SYKM096.RCRDKBN = #{recordkbn, jdbcType=VARCHAR} AND SYKM096.SETTEICD = #{setteicd0964, jdbcType=VARCHAR} ) LEFT OUTER JOIN S02M006T SYKM134 ON (SYKM134.APKIHONCD = #{apkihoncd000, jdbcType=VARCHAR} AND SYKM134.SHOPCD = #{shopcd000, jdbcType=VARCHAR} AND SYKM134.SETTEINO = #{setteino134, jdbcType=VARCHAR} AND SYKM134.RCRDKBN = #{recordkbn, jdbcType=VARCHAR} AND SYKM134.SETTEICD = #{setteicd13441, jdbcType=VARCHAR} ) WHERE JHTT.APKIHONCD = #{apkihoncd, jdbcType=VARCHAR} AND JHTT.SHOPCD = #{shopcd, jdbcType=VARCHAR}
AND JHTT.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND JHTT.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD
AND JHTT.DLVRYKYOTENCD = #{dlvrykyotencd, jdbcType=VARCHAR}
AND JHTT.APKIHONCD || JHTT.SHOPCD != JHTT.DLVRYKANKATSUAPKIHONCD || JHTT.DLVRYKANKATSUSHOPCD
AND JHTT.DLVRYJISSEKIPRCSDD IS NOT NULL AND JHTT.YUKOKBN = #{yukokbn, jdbcType=VARCHAR}
AND JHTT.DLVRYTNSHACD = #{dlvrytnshacd, jdbcType=VARCHAR}
AND JHTT.DLVRYKBN = #{dlvrykbn, jdbcType=VARCHAR}
AND JHTT.DLVRYCMPNYCD = #{dlvrykaisyacd, jdbcType=VARCHAR}
AND JHTT.TOKUISAKICD = #{tokuisakicd, jdbcType=VARCHAR}
AND JHTT.ACPTDNPYNO >= #{dnpynostr, jdbcType=VARCHAR}
AND JHTT.ACPTDNPYNO <= #{dnpynoend, jdbcType=VARCHAR}
AND JHTT.DLVRYAREACD IN
#{item,jdbcType=VARCHAR}
AND JHTT.DLVRYJISSEKIDD = #{dlvrydd, jdbcType=VARCHAR}
ORDER BY
JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD,
JHTT.DLVRYKYOTENCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYKBN, JHTT.DLVRYTNSHACD, JHTT.DLVRYCMPNYCD, JHTT.DLVRYJUN, S05GETDLVRYTIME(JHTT.DLVRYKIBOJIKANKBN,JHTT.DLVRYKIBOJIKAN), JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.APKIHONCD, JHTT.SHOPCD
JHTT.DLVRYKYOTENCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYKBN, JHTT.DLVRYCMPNYCD, JHTT.DLVRYTNSHACD, S05GETDLVRYTIME(JHTT.DLVRYKIBOJIKANKBN,JHTT.DLVRYKIBOJIKAN), JHTT.DLVRYAREACD, JHTT.DLVRYJUN, JHTT.ACPTDNPYNO DESC, JHTT.EDANO DESC, JHTT.APKIHONCD, JHTT.SHOPCD
JHTT.DLVRYKYOTENCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYAREACD, S05GETDLVRYTIME(JHTT.DLVRYKIBOJIKANKBN,JHTT.DLVRYKIBOJIKAN), JHTT.DLVRYJUN, JHTT.ACPTDNPYNO DESC, JHTT.EDANO DESC, JHTT.APKIHONCD, JHTT.SHOPCD
JHTT.DLVRYKYOTENCD, JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYCMPNYCD, JHTT.DLVRYTNSHACD, S05GETDLVRYTIME(JHTT.DLVRYKIBOJIKANKBN,JHTT.DLVRYKIBOJIKAN), JHTT.DLVRYAREACD, JHTT.DLVRYJUN, JHTT.ACPTDNPYNO, JHTT.EDANO
JHTT.DLVRYKYOTENCD, JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.DLVRYJISSEKIDD, JHTT.ACPTDNPYNO, JHTT.EDANO
JHTT.DLVRYKYOTENCD, JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.DLVRYJISSEKIDD, JHTT.TOKUISAKICD, JHTT.ACPTDNPYNO, JHTT.EDANO

SELECT
    *
FROM
    (
    SELECT
        JHTT.ACPTDNPYNO ACPTDNPYNO2MEI,
        JHTT.EDANO EDANO2MEI,
        JHTT.ACPTDD ACPTDD2MEI,
        JHTT.DLVRYDD DLVRYDD2MEI,
        JHTT.DLVRYYTIRGRAYUSYOHNS RGRAYURYO2MEI,
        JHTT.DLVRYYTIRGRAMUSHOHNS RGRAMURYO2MEI,
        JHTT.DLVRYYTISRMYUSYOHNS SRMYURYO2MEI,
        JHTT.DLVRYYTISRMMUSHOHNS SRMMURYO2MEI,
        JHTT.DLVRYYTISONOTAYUSYOHNS SONOTAYURYO2MEI,
        JHTT.DLVRYYTISONOTAMUSHOHNS SONOTAMURYO2MEI,
        JHTT.DLVRYYTISEIHINMIZUURIKIN SEIHINMIZUURI2MEI,
        JHTT.DLVRYYTISONOTAURIKIN SONOTAURI2MEI,
        SYKM2.MOJISETTEIATAI ACPTKBNNM,
        SYKM.MOJISETTEIATAI DNPYSTSNM2MEI
    FROM
        S04T001T JHTT
    LEFT OUTER JOIN
        S02M006T SYKM
        ON(
        SYKM.APKIHONCD = #{sysapkihoncd,jdbcType=VARCHAR}
        AND SYKM.SHOPCD = #{sysshopcd,jdbcType=VARCHAR}
        AND SYKM.SETTEINO = #{dnpystsno,jdbcType=VARCHAR}
        AND SYKM.RCRDKBN = #{sysrcrdkbn,jdbcType=VARCHAR}
        AND SYKM.SETTEICD = JHTT.DNPYSTS
        )
    LEFT OUTER JOIN
        S02M006T SYKM2
        ON(
        SYKM2.APKIHONCD = #{sysapkihoncd,jdbcType=VARCHAR}
        AND SYKM2.SHOPCD = #{sysshopcd,jdbcType=VARCHAR}
        AND SYKM2.SETTEINO = #{acptkbnno,jdbcType=VARCHAR}
        AND SYKM2.RCRDKBN = #{sysrcrdkbn,jdbcType=VARCHAR}
        AND SYKM2.SETTEICD = JHTT.ACPTKBN
        )
    WHERE
        JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
        AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
        AND JHTT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
        AND
        (
            JHTT.DNPYSTS = #{dnpystsdelivering,jdbcType=VARCHAR}
            OR
            JHTT.DNPYSTS IN (#{dnpystsjuchucancel,jdbcType=VARCHAR},#{dnpystshaitatsucancel,jdbcType=VARCHAR})
            AND JHTT.DLVRYDD > (
                SELECT NVL(ZNKDLVRYDD,#{dlvryddshokiatai,jdbcType=VARCHAR})
                FROM S02M050T
                WHERE
                    APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
                    AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
                    AND TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
                )
        )
        AND JHTT.YUKOKBN = #{yukokbn,jdbcType=VARCHAR}
    ORDER BY
        JHTT.ACPTDD DESC,
        JHTT.DLVRYYTIDD DESC,
        JHTT.ACPTDNPYNO DESC
    )
WHERE
    ROWNUM <= #{maxline,jdbcType=VARCHAR}

