= 'M' AND SYKM2.SETTEICD = JHTT.DATSKSMOTOKBN) LEFT OUTER JOIN S02M006T SYKM3 ON (SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '052' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = JHTT.ACPTKBN) LEFT OUTER JOIN S02M006T SYKM4 ON (SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.SETTEINO = '053' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEICD = JHTT.ACPTKBNSHS) LEFT OUTER JOIN S02M006T SYKM5 ON (SYKM5.APKIHONCD = '000' AND SYKM5.SHOPCD = '000' AND SYKM5.SETTEINO = '056' AND SYKM5.RCRDKBN = 'M' AND SYKM5.SETTEICD = TKSM.NOHINSAKIJOHON1) LEFT OUTER JOIN S02M006T SYKM6 ON (SYKM6.APKIHONCD = '000' AND SYKM6.SHOPCD = '000' AND SYKM6.SETTEINO = '057' AND SYKM6.RCRDKBN = 'M' AND SYKM6.SETTEICD = TKSM.NOHINSAKIJOHON2) LEFT OUTER JOIN S02M006T SYKM7 ON (SYKM7.APKIHONCD = '000' AND SYKM7.SHOPCD = '000' AND SYKM7.SETTEINO = '012' AND SYKM7.RCRDKBN = 'M' AND SYKM7.SETTEICD = JHTT.DLVRYKIBOJIKANKBN) WHERE JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
