ODD = '1' THEN '木' ELSE '' END || CASE WHEN HTAM.FRIDDLVRYKANODD = '1' THEN '金' ELSE '' END || CASE WHEN HTAM.SATDDLVRYKANODD = '1' THEN '土' ELSE '' END ) DLVRYPATERN, HTKM.DLVRYCMPNYNM, TTSM1.TNSHAMEI ACPTTNSHAMEI, TTSM2.TNSHAMEI DLVRYTNSHAMEI, SYKM1.MOJISETTEIATAI DNPYSTSMEI, SYKM2.MOJISETTEIATAI DATSKSMOTOKBNMEI, SYKM3.MOJISETTEIATAI ACPTKBNNM, SYKM4.MOJISETTEIATAI ACPTKBNSHSNM, SYKM5.MOJISETTEIATAI NOHINSAKIJOHONMEI1, SYKM6.MOJISETTEIATAI NOHINSAKIJOHONMEI2, SYKM7.MOJISETTEIATAI DLVRYKIBOJIKANKBNNM FROM S04T001T JHTT LEFT OUTER JOIN S02M013T TKSM ON(TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD) LEFT OUTER JOIN S02M017T SKSM ON(SKSM.APKIHONCD = JHTT.APKIHONCD AND SKSM.SHOPCD = JHTT.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD) LEFT OUTER JOIN S02M031T HKNM ON(HKNM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HKNM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HKNM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD) LEFT OUTER JOIN S02M018T HTAM ON(HTAM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM.DLVRYAREACD = JHTT.DLVRYAREACD AND NVL(JHTT.DLVRYYTIDD, #{unyodate,jdbcType=VARCHAR}) BETWEEN HTAM.TEKIYOSTRTDD AND HTAM.TEKIYOSHRYDD) LEFT OUTER JOIN S02M019T HTKM ON(HTKM.APKIHONCD = JHTT.APKIHONCD AND HTKM.SHOPCD = JHTT.SHOPCD AND HTKM.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD) LEFT OUTER JOIN S02M003T TTSM1 ON (TTSM1.APKIHONCD = JHTT.ACPTTNSHAAPKIHONCD AND TTSM1.SHOPCD = JHTT.ACPTTNSHASHOPCD AND TTSM1.TNSHACD = JHTT.ACPTTNSHACD) LEFT OUTER JOIN S02M003T TTSM2 ON (TTSM2.APKIHONCD = JHTT.APKIHONCD AND TTSM2.SHOPCD = JHTT.SHOPCD AND TTSM2.TNSHACD = JHTT.DLVRYTNSHACD) LEFT OUTER JOIN S02M006T SYKM1 ON (SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '026' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = JHTT.DNPYSTS) LEFT OUTER JOIN S02M006T SYKM2 ON (SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '093' AND SYKM2.RCRDKBN 