SELECT TO_CHAR(SYSDATE, 'YYYYMMDD') AS YMD, JHTT.ACPTDNPYNO, TO_CHAR(JHTT.EDANO, 'FM00') AS EDANO, SYKM052.MOJISETTEIATAI AS ACPTKBN, JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.TOKUISAKICD, TKSM.JIGYOSHOCD, TKSM.YUBINNO, TKSM.ADRSN1, TKSM.ADRSN2, TKSM.ADRSN3, TKSM.RENRAKUSAKINOKBNN1, TKSM.RENRAKUSAKINON1, TKSM.RENRAKUSAKINOKBNN2, TKSM.RENRAKUSAKINON2, TKSM.RENRAKUSAKINOKBNN3, TKSM.RENRAKUSAKINON3, TKSM.RENRAKUSAKINOKBNN4, TKSM.RENRAKUSAKINON4, TKSM.TOKUISAKINMN1, TKSM.TOKUISAKINMN2, TKSM.TOKUISAKIKEISHOKBN, TKSM.CHIZUNO, TKSM.NYUKAIDD, TKSM.SHOKAIWSVSTUPDD, JHTT.ACPTDD, JHTT.DLVRYYTIDD, JHTT.DLVRYKIBOJIKAN, JHTT.DLVRYKIBOJIKANSHRY, JHTT.DLVRYKIBOJIKANKBN, JHTT.DLVRYJUN, JHTT.FZAIOKIKANOFLG, TTSM_DLVRY.TNSHAMEI AS DLVRYTNSHAMEI, TTSM_EIGYO.TNSHAMEI AS EIGYOTNSHAMEI, SYKM012.MOJISETTEIATAI AS DLVRYKIBOJIKANNM, SYKM056.MOJISETTEIATAI AS NOHINSAKIJOHON1, SYKM057.MOJISETTEIATAI AS NOHINSAKIJOHON2, SYKM051.MOJISETTEIATAI AS KAISHUHOHO, ' ' AS KEIJOKBN, HTAM.DLVRYAREANM, HTAM.DLVRYSHUA, HTAM.DLVRYSHUB, HTAM.DLVRYSHUC, HTAM.DLVRYSHUD, HTAM.SUNDDLVRYKANODD, HTAM.MONDDLVRYKANODD, HTAM.TUEDDLVRYKANODD, HTAM.WEDDDLVRYKANODD, HTAM.THEDDLVRYKANODD, HTAM.FRIDDLVRYKANODD, HTAM.SATDDLVRYKANODD, SHMV.IRO, SHMV.SZNM, SHMV.SHNNMKIRIKAEDD, SHMV.GENZSHNNM, SHMV.SHINSHNNM, NVL(JHMT.ACPTSURYO, 0) AS ACPTSURYO, JHMT.KATASIKI, JHMT.SHNCD ,TKSM.TOKUISAKIKBN ,SHPM.SHOPNM AS TORIATSUKAITENNM FROM S04T001T JHTT INNER JOIN S04T002T JHMT ON( JHMT.APKIHONCD = JHTT.APKIHONCD AND JHMT.SHOPCD = JHTT.SHOPCD AND JHMT.ACPTDNPYNO = JHTT.ACPTDNPYNO AND JHMT.EDANO = JHTT.EDANO AND JHMT.MEISAIKBN <> '1'
