AND JHMT.LCTGRYCD = #{category,jdbcType=VARCHAR} AND (JHMT.MCTGRYCD = #{subcategory,jdbcType=VARCHAR} OR JHMT.MCTGRYCD = #{panelsubcategory,jdbcType=VARCHAR} )
) INNER JOIN S02M013T TKSM ON( TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD ) LEFT OUTER JOIN S02M003T TTSM_DLVRY ON( TTSM_DLVRY.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND TTSM_DLVRY.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND TTSM_DLVRY.TNSHACD = JHTT.DLVRYTNSHACD ) LEFT OUTER JOIN S02M003T TTSM_EIGYO ON( TTSM_EIGYO.APKIHONCD = TKSM.APKIHONCD AND TTSM_EIGYO.SHOPCD = TKSM.SHOPCD AND TTSM_EIGYO.TNSHACD = TKSM.EIGYOTNSHACD ) LEFT OUTER JOIN S02M018T HTAM ON( HTAM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM.DLVRYAREACD = JHTT.DLVRYAREACD AND HTAM.TEKIYOSTRTDD <= #{unyodate,jdbcType=VARCHAR} AND HTAM.TEKIYOSHRYDD >= #{unyodate,jdbcType=VARCHAR} ) LEFT OUTER JOIN S02M006T SYKM012 ON( SYKM012.APKIHONCD = '000' AND SYKM012.SHOPCD = '000' AND SYKM012.SETTEINO = '012' AND SYKM012.RCRDKBN = 'M' AND SYKM012.SETTEICD = JHTT.DLVRYKIBOJIKANKBN ) LEFT OUTER JOIN S02M006T SYKM056 ON( SYKM056.APKIHONCD = '000' AND SYKM056.SHOPCD = '000' AND SYKM056.SETTEINO = '056' AND SYKM056.RCRDKBN = 'M' AND SYKM056.SETTEICD = TKSM.NOHINSAKIJOHON1 ) LEFT OUTER JOIN S02M006T SYKM057 ON( SYKM057.APKIHONCD = '000' AND SYKM057.SHOPCD = '000' AND SYKM057.SETTEINO = '057' AND SYKM057.RCRDKBN = 'M' AND SYKM057.SETTEICD = TKSM.NOHINSAKIJOHON2 ) LEFT OUTER JOIN S02M017T SKSM ON( SKSM.APKIHONCD = TKSM.APKIHONCD AND SKSM.SHOPCD = TKSM.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD ) LEFT OUTER JOIN S02M006T SYKM051 ON( SYKM051.APKIHONCD = '000' AND SYKM051.SHOPCD = '000' AND SYKM051.SETTEINO = '051' AND SYKM051.RCRDKBN = 'M' AND SYKM051.SETTEICD = SKSM.KAISHUHOHOKBN ) LEFT OUTER JOIN S02M006T SYKM052 ON( SYKM052.APKIHONCD = '000' AND SYKM052.SHOPCD = '000' AND SYKM052.SETTEINO = '052' AND SYKM052.RCRDKBN = 'M' AND SYKM052.SETTEICD = JHTT.ACPTKBN ) LEFT OUTER JOIN S02V001T SHMV ON( SHMV.APKIHONCD = JHMT.APKIHONCD AND SHMV.SHOPCD = JHMT.SHOPCD AND SHMV.SHNCD = JHMT.SHNCD ) LEFT OUTER JOIN S02M046T SHPM ON( SHPM.APKIHONCD = TKSM.APKIHONCD AND SHPM.SHOPCD = TKSM.TOKUISAKISHOPCD ) WHERE JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND JHTT.ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR} AND JHTT.EDANO = #{edano,jdbcType=VARCHAR} AND JHTT.ACPTKBN IN ('2','3','4','5') AND JHTT.ACPTKBNSHS <> '43' ORDER BY JHTT.ACPTDNPYNO ,JHTT.EDANO ,SIGN(JHMT.ACPTSURYO) DESC ,JHMT.ACPTDNPYMEISAINO ,JHMT.ACPTDNPYMEISAIEDANO

SELECT
  SYKM012.MOJISETTEIATAI AS DLVRYKIBOJIKANNM,
  SYKM056.MOJISETTEIATAI AS NOHINSAKIJOHON1,
  SYKM057.MOJISETTEIATAI AS NOHINSAKIJOHON2,
  SYKM051.MOJISETTEIATAI AS KAISHUHOHO,
  SYKM014.MOJISETTEIATAI AS TOKUISAKIJOTAI,
  JHTT.ACPTDNPYNO AS ACPTDNPYNO,
  JHTT.EDANO AS EDANO
FROM
  S04T001T JHTT
INNER JOIN
  S02M013T TKSM
ON
(
  TKSM.APKIHONCD = JHTT.APKIHONCD
  AND TKSM.SHOPCD = JHTT.SHOPCD
  AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD
)
LEFT JOIN
  S02M017T SKSM
ON
(
  SKSM.APKIHONCD = TKSM.APKIHONCD
  AND SKSM.SHOPCD = TKSM.SHOPCD
  AND SKSM.SKYSAKICD = TKSM.SKYSAKICD
)
LEFT JOIN
  S02M006T SYKM012
ON
(
  SYKM012.APKIHONCD = #{sys_apkihoncd,jdbcType=VARCHAR}
  AND SYKM012.SHOPCD = #{sys_shopcd,jdbcType=VARCHAR}
  AND SYKM012.SETTEINO = #{setteino_012,jdbcType=VARCHAR}
  AND SYKM012.RCRDKBN = #{sys_recordkbn,jdbcType=VARCHAR}
  AND SYKM012.SETTEICD = JHTT.DLVRYKIBOJIKANKBN
)
LEFT JOIN
  S02M006T SYKM051
ON
(
  SYKM051.APKIHONCD = #{sys_apkihoncd,jdbcType=VARCHAR}
  AND SYKM051.SHOPCD = #{sys_shopcd,jdbcType=VARCHAR}
  AND SYKM051.SETTEINO = #{setteino_051,jdbcType=VARCHAR}
  AND SYKM051.RCRDKBN = #{sys_recordkbn,jdbcType=VARCHAR}
  AND SYKM051.SETTEICD = SKSM.KAISHUHOHOKBN
)
LEFT JOIN
  S02M006T SYKM056
ON
(
  SYKM056.APKIHONCD = #{sys_apkihoncd,jdbcType=VARCHAR}
  AND SYKM056.SHOPCD = #{sys_shopcd,jdbcType=VARCHAR}
  AND SYKM056.SETTEINO = #{setteino_056,jdbcType=VARCHAR}
  AND SYKM056.RCRDKBN = #{sys_recordkbn,jdbcType=VARCHAR}
  AND SYKM056.SETTEICD = TKSM.NOHINSAKIJOHON1
)
LEFT JOIN
  S02M006T SYKM057
ON
(
  SYKM057.APKIHONCD = #{sys_apkihoncd,jdbcType=VARCHAR}
  AND SYKM057.SHOPCD = #{sys_shopcd,jdbcType=VARCHAR}
  AND SYKM057.SETTEINO = #{setteino_057,jdbcType=VARCHAR}
  AND SYKM057.RCRDKBN = #{sys_recordkbn,jdbcType=VARCHAR}
  AND SYKM057.SETTEICD = TKSM.NOHINSAKIJOHON2
)
LEFT JOIN
  S02M006T SYKM014
ON
(
  SYKM014.APKIHONCD = #{sys_apkihoncd,jdbcType=VARCHAR}
  AND SYKM014.SHOPCD = #{sys_shopcd,jdbcType=VARCHAR}
  AND SYKM014.SETTEINO = #{setteino_014,jdbcType=VARCHAR}
  AND SYKM014.RCRDKBN = #{sys_recordkbn,jdbcType=VARCHAR}
  AND SYKM014.SETTEICD = TKSM.TOKUISAKIJOTAI
)
LEFT JOIN
  S02M046T SHPM
ON
(
  SHPM.APKIHONCD = JHTT.APKIHONCD
  AND SHPM.SHOPCD = JHTT.SHOPCD
)
WHERE
  JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
  AND JHTT.ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR}
  AND JHTT.EDANO = #{edano,jdbcType=VARCHAR}
ORDER BY
  JHTT.ACPTDNPYNO,
  JHTT.EDANO

SELECT DLVRYDD, DNPYNO, KIN FROM (
SELECT '' AS DLVRYDD, '前回繰越額' AS DNPYNO, NVL(ZNKKURIKOSHIKIN, 0) AS KIN, '0' AS KINKBN FROM S04T001T WHERE APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SHOPCD = #{shopcd,jdbcType=VARCHAR} AND ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR} AND EDANO = #{edano,jdbcType=VARCHAR} AND YUKOKBN = #{yukokbn,jdbcType=VARCHAR} UNION ALL
SELECT DLVRYDD AS DLVRYDD, CASE WHEN DNPYSTS = '12' THEN URIDNPYNO ELSE ACPTDNPYNO END AS DNPYNO, CASE WHEN DNPYSTS = '12' THEN NOHINKIN + NOHINSHOHITAXKIN ELSE ACPTKIN + ACPTSHOHITAXKIN END AS KIN, '1' AS KINKBN FROM S04T001T WHERE APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SHOPCD = #{shopcd,jdbcType=VARCHAR} AND ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR} AND EDANO = #{edano,jdbcType=VARCHAR} AND YUKOKBN = #{yukokbn,jdbcType=VARCHAR}
UNION ALL SELECT URIDD AS DLVRYDD, URIDNPYNO AS DNPYNO, NVL(URIKIN, 0) + NVL(SHOHITAXKIN, 0) AS URIKIN, '2' AS KINKBN FROM S06T001T WHERE APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SHOPCD = #{shopcd,jdbcType=VARCHAR} AND ACPTDNPYNO = #{acptdnpyno,jdbcType=VARCHAR} AND ACPTDNPYEDANO = #{edano,jdbcType=VARCHAR} AND ACPTDNPYNO <> URIDNPYNO AND SKYSHIMEDYDM IS NULL AND SKYSHIMEDD IS NULL AND SKYSHOOTPTARINASHIKBN = '0' AND YUKOKBN = #{yukokbn,jdbcType=VARCHAR}
) ORDER BY KINKBN, DNPYNO, KINKBN

SELECT JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, ( SELECT SHPM1.SHOPNM FROM S02M046T SHPM1 WHERE SHPM1.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND SHPM1.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD ) AS SHOPNM1, JHTT.DLVRYKYOTENCD, ( SELECT HKNM.DLVRYKYOTENNM FROM S02M031T HKNM WHERE HKNM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HKNM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HKNM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD ) AS DLVRYKYOTENNM, ( SELECT TTSM1.TNSHAMEI FROM S02M003T TTSM1 WHERE TTSM1.APKIHONCD = #{loginapkihoncd,jdbcType=VARCHAR} AND TTSM1.SHOPCD = #{loginshopcd,jdbcType=VARCHAR} AND TTSM1.TNSHACD = #{logintnshacd,jdbcType=VARCHAR} ) AS TNSHAMEI1,
( SELECT HTKM.DLVRYCMPNYNM FROM S02M019T HTKM WHERE HTKM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTKM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTKM.DLVRYCMPNYCD =JHTT.DLVRYCMPNYCD ) AS DLVRYCMPNYNM, ( SELECT TTSM2.TNSHAMEI FROM S02M003T TTSM2 WHERE TTSM2.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND TTSM2.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND TTSM2.TNSHACD = JHTT.DLVRYTNSHACD ) AS TNSHAMEI2, JHTT.DLVRYKBN,
JHTT.DLVRYTNSHACD, JHTT.DLVRYCMPNYCD,
( SELECT HTAM.DLVRYAREANM FROM S02M018T HTAM WHERE HTAM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM.DLVRYAREACD = JHTT.DLVRYAREACD AND HTAM.TEKIYOSTRTDD(+) <= #{unyodate,jdbcType=VARCHAR} AND HTAM.TEKIYOSHRYDD(+) >= #{unyodate,jdbcType=VARCHAR} ) AS DLVRYAREANM,
( SELECT SHPM2.SHOPNM FROM S02M046T SHPM2 WHERE SHPM2.APKIHONCD = JHTT.APKIHONCD AND SHPM2.SHOPCD = JHTT.SHOPCD ) AS SHOPNM2,
JHTT.DLVRYJISSEKIDD, JHTT.DLVRYSTS_0, JHTT.DLVRYSTS_1, JHTT.DLVRYSTS_2, JHTT.DLVRYSTS_3, JHTT.DLVRYSTS_4, JHTT.DLVRYJISSEKIRGRAYUSYOHNS, JHTT.DLVRYJISSEKIRGRAMUSHOHNS, JHTT.DLVRYJISSEKISRMYUSYOHNS, JHTT.DLVRYJISSEKISRMMUSHOHNS, JHTT.DLVRYJISSEKISTYSHNS, JHTT.DLVRYJISSEKISTMSHNS, JHTT.KYBTLN1N2RITTORUHNS, JHTT.KZBTLN1N2RITTORUHNS, JHTT.KYBTLN8RITTORUHNS, JHTT.KZBTLN8RITTORUHNS, JHTT.DLVRYJISSEKISHSUAKIN, JHTT.DLVRYJISSEKISONOTAURIKIN, JHTT.KURERURITTORUSTUP, JHTT.KURERURITTORUHIKIAGE, JHTT.KURERUESUSTUP, JHTT.KURERUESUHIKIAGE, JHTT.SONOTASTUP, JHTT.SONOTAHIKIAGE, NVL(JHTT_SEIHINSUI.SHNCD,0) AS SHNCD, NVL(JHTT_SEIHINSUI.ACPTSURYO, 0) AS ACPTSURYO, CASE WHEN JHTT_SEIHINSUI.LCTGRYCD = SYKM096.MOJISETTEIATAI THEN SYKM096.MOJISETTEIATAI END AS LCTGRYCD, CASE WHEN JHTT_SEIHINSUI.MCTGRYCD = SYKM134.MOJISETTEIATAI THEN SYKM134.MOJISETTEIATAI END AS MCTGRYCD, JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.NOHINSHOHITAXKIN FROM ( SELECT JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHTT.DLVRYKBN, JHTT.DLVRYJISSEKIDD,
JHTT.DLVRYCMPNYCD, JHTT.DLVRYTNSHACD,
JHTT.DLVRYAREACD,
SUM( CASE WHEN JHTT.DLVRYSTS = '12' THEN 1 ELSE 0 END ) DLVRYSTS_0, SUM( CASE WHEN JHTT.DLVRYSTS = '12' AND JHTT.EDANO > 0 THEN 1 ELSE 0 END ) DLVRYSTS_1, SUM( CASE WHEN JHTT.DLVRYSTS = '14' THEN 1 ELSE 0 END ) DLVRYSTS_2, SUM( CASE WHEN JHTT.DLVRYSTS = '13' THEN 1 ELSE 0 END ) DLVRYSTS_3, SUM( CASE WHEN JHTT.DLVRYSTS = '19' THEN 1 ELSE 0 END ) DLVRYSTS_4, NVL( SUM(JHTT.DLVRYJISSEKIRGRAYUSYOHNS), 0 ) DLVRYJISSEKIRGRAYUSYOHNS, NVL( SUM(JHTT.DLVRYJISSEKIRGRAMUSHOHNS), 0 ) DLVRYJISSEKIRGRAMUSHOHNS, NVL( SUM(JHTT.DLVRYJISSEKISRMYUSYOHNS), 0 ) DLVRYJISSEKISRMYUSYOHNS, NVL( SUM(JHTT.DLVRYJISSEKISRMMUSHOHNS), 0 ) DLVRYJISSEKISRMMUSHOHNS, NVL( SUM(JHTT.DLVRYJISSEKISTYSHNS), 0 ) DLVRYJISSEKISTYSHNS, NVL( SUM(JHTT.DLVRYJISSEKISTMSHNS), 0 ) DLVRYJISSEKISTMSHNS, NVL( SUM(JHTT.KYBTLN1N2RITTORUHNS), 0 ) KYBTLN1N2RITTORUHNS, NVL( SUM(JHTT.KZBTLN1N2RITTORUHNS), 0 ) KZBTLN1N2RITTORUHNS, NVL( SUM(JHTT.KYBTLN8RITTORUHNS), 0 ) KYBTLN8RITTORUHNS, NVL( SUM(JHTT.KZBTLN8RITTORUHNS), 0 ) KZBTLN8RITTORUHNS, NVL( SUM(JHTT.DLVRYJISSEKISHSUAKIN), 0 ) DLVRYJISSEKISHSUAKIN, NVL( SUM(JHTT.DLVRYJISSEKISONOTAURIKIN), 0 ) DLVRYJISSEKISONOTAURIKIN, NVL( SUM(JHTT.KURERURITTORUSTUP), 0 ) KURERURITTORUSTUP, NVL( SUM(JHTT.KURERURITTORUHIKIAGE), 0 ) KURERURITTORUHIKIAGE, NVL( SUM(JHTT.KURERUESUSTUP), 0 ) KURERUESUSTUP, NVL( SUM(JHTT.KURERUESUHIKIAGE), 0 ) KURERUESUHIKIAGE, NVL( SUM(JHTT.SONOTASTUP), 0 ) SONOTASTUP, NVL( SUM(JHTT.SONOTAHIKIAGE), 0 ) SONOTAHIKIAGE, JHTT.EDANO, JHTT.ACPTDNPYNO, JHTT.SHOPCD, JHTT.APKIHONCD, SUM( CASE WHEN SHPM0.INVOICSHIKOYMD > JHTT.DLVRYDD THEN NVL(JHTT.NOHINSHOHITAXKIN, 0) WHEN (SHPM0.INVOICSHIKOYMD <= JHTT.DLVRYDD) AND (JHTT.ACPTTHDAIBIKIFLG = '1' OR JHTT.SINGLDNPYFLG = '1') THEN NVL(JHTT.NOHINSHOHITAXKIN, 0) ELSE 0 END ) NOHINSHOHITAXKIN FROM S04T001T JHTT INNER JOIN S02M046T SHPM0 ON ( SHPM0.APKIHONCD = JHTT.APKIHONCD AND SHPM0.SHOPCD = JHTT.SHOPCD ) WHERE JHTT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND JHTT.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND JHTT.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD
AND JHTT.DLVRYKYOTENCD = #{dlvrykyotencd,jdbcType=VARCHAR}
AND JHTT.APKIHONCD || JHTT.SHOPCD != JHTT.DLVRYKANKATSUAPKIHONCD || JHTT.DLVRYKANKATSUSHOPCD
AND JHTT.DLVRYJISSEKIPRCSDD IS NOT NULL AND JHTT.YUKOKBN = '1'
AND JHTT.DLVRYTNSHACD = #{dlvrytnshacd,jdbcType=VARCHAR}
AND JHTT.DLVRYKBN = #{dlvrykbn,jdbcType=VARCHAR}
AND JHTT.DLVRYCMPNYCD = #{dlvrykaisyacd,jdbcType=VARCHAR}
AND JHTT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND JHTT.ACPTDNPYNO >= #{dnpynostr,jdbcType=VARCHAR}
AND JHTT.ACPTDNPYNO <= #{dnpynoend,jdbcType=VARCHAR}
AND JHTT.DLVRYAREACD IN (
#{item,jdbcType=VARCHAR}
)
AND JHTT.DLVRYJISSEKIDD LIKE #{dlvrymonth,jdbcType=VARCHAR} || '%'
GROUP BY
JHTT.DLVRYKBN, JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYCMPNYCD, JHTT.DLVRYTNSHACD, JHTT.EDANO, JHTT.ACPTDNPYNO, JHTT.SHOPCD, JHTT.APKIHONCD, JHTT.DLVRYAREACD
JHTT.DLVRYKBN, JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYCMPNYCD, JHTT.DLVRYTNSHACD, JHTT.EDANO, JHTT.ACPTDNPYNO, JHTT.SHOPCD, JHTT.APKIHONCD
JHTT.DLVRYAREACD, JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYKBN, JHTT.EDANO, JHTT.ACPTDNPYNO, JHTT.SHOPCD, JHTT.APKIHONCD
JHTT.APKIHONCD, JHTT.SHOPCD, JHTT.DLVRYJISSEKIDD, JHTT.DLVRYKANKATSUAPKIHONCD, JHTT.DLVRYKANKATSUSHOPCD, JHTT.DLVRYKYOTENCD, JHTT.EDANO, JHTT.ACPTDNPYNO, JHTT.DLVRYKBN
) JHTT LEFT OUTER JOIN ( SELECT JHTT_SUB.APKIHONCD, JHTT_SUB.SHOPCD, JHTT_SUB.ACPTDNPYNO, JHTT_SUB.EDANO, JHMT_SUB.SHNCD, SUM(NOHINSURYO) AS ACPTSURYO, JHMT_SUB.LCTGRYCD AS LCTGRYCD, JHMT_SUB.MCTGRYCD AS MCTGRYCD, JHMT_SUB.ACPTDNPYMEISAINO AS ACPTDNPYMEISAINO, JHMT_SUB.ACPTDNPYMEISAIEDANO AS ACPTDNPYMEISAIEDANO FROM S04T001T JHTT_SUB INNER JOIN S04T002T JHMT_SUB ON( JHMT_SUB.APKIHONCD = JHTT_SUB.APKIHONCD AND JHMT_SUB.SHOPCD = JHTT_SUB.SHOPCD AND JHMT_SUB.ACPTDNPYNO = JHTT_SUB.ACPTDNPYNO AND JHMT_SUB.EDANO = JHTT_SUB.EDANO ) WHERE JHTT_SUB.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND JHTT_SUB.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND JHTT_SUB.APKIHONCD = JHTT_SUB.DLVRYKANKATSUAPKIHONCD AND JHTT_SUB.SHOPCD = JHTT_SUB.DLVRYKANKATSUSHOPCD
AND JHTT_SUB.DLVRYKYOTENCD = #{dlvrykyotencd,jdbcType=VARCHAR}
AND JHTT_SUB.APKIHONCD || JHTT_SUB.SHOPCD != JHTT_SUB.DLVRYKANKATSUAPKIHONCD || JHTT_SUB.DLVRYKANKATSUSHOPCD
AND JHTT_SUB.DLVRYJISSEKIPRCSDD IS NOT NULL AND JHTT_SUB.YUKOKBN = '1'
AND JHTT_SUB.DLVRYTNSHACD = #{dlvrytnshacd,jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYKBN = #{dlvrykbn,jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYCMPNYCD = #{dlvrykaisyacd,jdbcType=VARCHAR}
AND JHTT_SUB.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND JHTT_SUB.ACPTDNPYNO >= #{dnpynostr,jdbcType=VARCHAR}
AND JHTT_SUB.ACPTDNPYNO <= #{dnpynoend,jdbcType=VARCHAR}
AND JHTT_SUB.DLVRYAREACD IN (
#{item,jdbcType=VARCHAR}
)
AND JHTT_SUB.DLVRYJISSEKIDD LIKE #{dlvrymonth,jdbcType=VARCHAR} || '%'
AND JHTT_SUB.DLVRYJISSEKIDD = #{dlvryday,jdbcType=VARCHAR}
GROUP BY JHTT_SUB.APKIHONCD, JHTT_SUB.SHOPCD, JHTT_SUB.ACPTDNPYNO, JHTT_SUB.EDANO, JHMT_SUB.SHNCD, JHMT_SUB.LCTGRYCD, JHMT_SUB.MCTGRYCD, JHMT_SUB.ACPTDNPYMEISAINO, JHMT_SUB.ACPTDNPYMEISAIEDANO ) JHTT_SEIHINSUI ON( JHTT.APKIHONCD = JHTT_SEIHINSUI.APKIHONCD AND JHTT.SHOPCD = JHTT_SEIHINSUI.SHOPCD AND JHTT.ACPTDNPYNO = JHTT_SEIHINSUI.ACPTDNPYNO AND JHTT.EDANO = JHTT_SEIHINSUI.EDANO ) LEFT OUTER JOIN S02M006T SYKM096 ON( SYKM096.APKIHONCD = '000' AND SYKM096.SHOPCD = '000' AND SYKM096.SETTEINO = '096' AND SYKM096.RCRDKBN = 'M' AND SYKM096.SETTEICD = '4' ) LEFT OUTER JOIN S02M006T SYKM134 ON( SYKM134.APKIHONCD = '000' AND SYKM134.SHOPCD = '000' AND SYKM134.SETTEINO = '134' AND SYKM134.RCRDKBN = 'M' AND SYKM134.SETTEICD = '41' ) ORDER BY
JHTT.DLVRYKYOTENCD, JHTT.DLVRYKBN, JHTT.DLVRYTNSHACD, JHTT.DLVRYCMPNYCD, JHTT.DLVRYJISSEKIDD, JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.APKIHONCD, JHTT.SHOPCD
JHTT.DLVRYKYOTENCD, JHTT.DLVRYKBN, JHTT.DLVRYCMPNYCD, JHTT.DLVRYTNSHACD, JHTT.DLVRYJISSEKIDD, JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.APKIHONCD, JHTT.SHOPCD
JHTT.DLVRYKYOTENCD, JHTT.DLVRYAREACD, JHTT.DLVRYJISSEKIDD, JHTT.ACPTDNPYNO, JHTT.EDANO, JHTT.APKIHONCD, JHTT.SHOPCD
