SELECT JHTT.APKIHONCD , JHTT.SHOPCD , JHTT.ACPTDNPYNO , JHTT.EDANO , JHTT.ITAKUAITEAPKIHONCD , JHTT.ITAKUAITESHOPCD , JHTT.ITAKUAITEACPTDNPYNO , JHTT.ITAKUAITEEDANO , JHTT.URIDNPYNO , JHTT.DLVRYTRGTFLG , JHTT.DNPYKBN , JHTT.TORIHIKIKBN , JHTT.ACPTKBN , JHTT.ACPTKBNSHS , JHTT.TOKUISAKICD , JHTT.ACPTDD , JHTT.ACPTTNSHAAPKIHONCD , JHTT.ACPTTNSHASHOPCD , JHTT.ACPTTNSHACD , JHTT.DLVRYYTIDD , JHTT.DLVRYJISSEKIDD , JHTT.DLVRYDD , JHTT.DLVRYKIBOJIKAN , JHTT.DLVRYKIBOJIKANKBN , JHTT.DLVRYKIBOJIKANSHRY , JHTT.FZAIOKIKANOFLG , JHTT.FZAIOKIJISSEKIFLG , JHTT.DLVRYTNSHACD , JHTT.DLVRYKANKATSUAPKIHONCD , JHTT.DLVRYKANKATSUSHOPCD , JHTT.DLVRYKYOTENCD , JHTT.DLVRYAREACD , JHTT.DLVRYKBN , JHTT.DLVRYCMPNYCD , JHTT.AZUKARIBTLN1N2RITTORUHNS , JHTT.KYBTLN1N2RITTORUHNS , JHTT.KZBTLN1N2RITTORUHNS , JHTT.AZUKARIBTLN8RITTORUHNS , JHTT.KYBTLN8RITTORUHNS , JHTT.KZBTLN8RITTORUHNS , JHTT.PRNTMEMON1 , JHTT.PRNTMEMON2 , JHTT.PRNTMEMON3 , JHTT.DLVRYJISSEKIPRCSDD , JHTT.SINGLDNPYFLG , JHTT.DNPYSTS , JHTT.ACPTSTS , JHTT.DATSKSMOTOKBN , JHTT.DLVRYJISSEKIRGRAYUSYOHNS , JHTT.DLVRYJISSEKIRGRAMUSHOHNS , JHTT.DLVRYJISSEKISRMYUSYOHNS , JHTT.DLVRYJISSEKISRMMUSHOHNS , JHTT.DLVRYJISSEKISTYSHNS , JHTT.DLVRYJISSEKISTMSHNS , JHTT.DLVRYJISSEKISHSUAKIN , JHTT.DLVRYJISSEKISONOTAURIKIN , JHTT.ACPTKIN , JHTT.ACPTSHOHITAXKIN , JHTT.NOHINKIN , JHTT.NOHINSHOHITAXKIN , JHTT.YUKOKBN , JHTT.KSHNSYSTMYMD , JHTT.KSHNSYSTMJIKAN , JHTT.ACPTRCPTKEIROKBN , SKSM.KAISHUHOHOKBN , JHTT.ACPTTHDAIBIKIFLG , TKSM.SKYSAKICD , TKSM.JOTAISTS , TKSM.ACPTTEISHIFLG , TKSM.TOKUISAKIKBN , HKNM.DLVRYKYOTENNM , HTAM.DLVRYAREANM , ( CASE WHEN HTAM.DLVRYSHUA = '1' THEN 'A' ELSE '' END || CASE WHEN HTAM.DLVRYSHUB = '1' THEN 'B' ELSE '' END || CASE WHEN HTAM.DLVRYSHUC = '1' THEN 'C' ELSE '' END || CASE WHEN HTAM.DLVRYSHUD = '1' THEN 'D' ELSE '' END || ' ' || CASE WHEN HTAM.SUNDDLVRYKANODD = '1' THEN '日' ELSE '' END || CASE WHEN HTAM.MONDDLVRYKANODD = '1' THEN '月' ELSE '' END || CASE WHEN HTAM.TUEDDLVRYKANODD = '1' THEN '火' ELSE '' END || CASE WHEN HTAM.WEDDDLVRYKANODD = '1' THEN '水' ELSE '' END || CASE WHEN HTAM.THEDDLVRYKANODD = '1' THEN '木' ELSE '' END || CASE WHEN HTAM.FRIDDLVRYKANODD = '1' THEN '金' ELSE '' END || CASE WHEN HTAM.SATDDLVRYKANODD = '1' THEN '土' ELSE '' END ) DLVRYPATERN , HTKM.DLVRYCMPNYNM , TTSM1.TNSHAMEI ACPTTNSHAMEI , TTSM2.TNSHAMEI DLVRYTNSHAMEI , SYKM1.MOJISETTEIATAI DNPYSTSMEI , SYKM2.MOJISETTEIATAI DATSKSMOTOKBNMEI , SYKM3.MOJISETTEIATAI ACPTKBNNM , SYKM4.MOJISETTEIATAI ACPTKBNSHSNM , SYKM5.MOJISETTEIATAI NOHINSAKIJOHONMEI1 , SYKM6.MOJISETTEIATAI NOHINSAKIJOHONMEI2 , SYKM7.MOJISETTEIATAI DLVRYKIBOJIKANKBNNM FROM S04T001T JHTT LEFT OUTER JOIN S02M013T TKSM ON ( TKSM.APKIHONCD = JHTT.APKIHONCD AND TKSM.SHOPCD = JHTT.SHOPCD AND TKSM.TOKUISAKICD = JHTT.TOKUISAKICD ) LEFT OUTER JOIN S02M017T SKSM ON ( SKSM.APKIHONCD = JHTT.APKIHONCD AND SKSM.SHOPCD = JHTT.SHOPCD AND SKSM.SKYSAKICD = TKSM.SKYSAKICD ) LEFT OUTER JOIN S02M031T HKNM ON ( HKNM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HKNM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HKNM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD ) LEFT OUTER JOIN S02M018T HTAM ON ( HTAM.APKIHONCD = JHTT.DLVRYKANKATSUAPKIHONCD AND HTAM.SHOPCD = JHTT.DLVRYKANKATSUSHOPCD AND HTAM.DLVRYKYOTENCD = JHTT.DLVRYKYOTENCD AND HTAM.DLVRYAREACD = JHTT.DLVRYAREACD AND NVL( JHTT.DLVRYYTIDD , #{unyoymd, jdbcType = VARCHAR} ) BETWEEN HTAM.TEKIYOSTRTDD AND HTAM.TEKIYOSHRYDD ) LEFT OUTER JOIN S02M019T HTKM ON ( HTKM.APKIHONCD = JHTT.APKIHONCD AND HTKM.SHOPCD = JHTT.SHOPCD AND HTKM.DLVRYCMPNYCD = JHTT.DLVRYCMPNYCD ) LEFT OUTER JOIN S02M003T TTSM1 ON ( TTSM1.APKIHONCD = JHTT.ACPTTNSHAAPKIHONCD AND TTSM1.SHOPCD = JHTT.ACPTTNSHASHOPCD AND TTSM1.TNSHACD = JHTT.ACPTTNSHACD ) LEFT OUTER JOIN S02M003T TTSM2 ON ( TTSM2.APKIHONCD = JHTT.APKIHONCD AND TTSM2.SHOPCD = JHTT.SHOPCD AND TTSM2.TNSHACD = JHTT.DLVRYTNSHACD ) LEFT OUTER JOIN S02M006T SYKM1 ON ( SYKM1.APKIHONCD = #{sysApkihoncd, jdbcType = VARCHAR} AND SYKM1.SHOPCD = #{sysShopcd, jdbcType = VARCHAR} AND SYKM1.SETTEINO = #{dnpystssttno, jdbcType = VARCHAR} AND SYKM1.RCRDKBN = #{sysRcrdKbn, jdbcType = VARCHAR} AND SYKM1.SETTEICD = JHTT.DNPYSTS ) LEFT OUTER JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = #{sysApkihoncd, jdbcType = VARCHAR} AND SYKM2.SHOPCD = #{sysShopcd, jdbcType = VARCHAR} AND SYKM2.SETTEINO = #{dtsksmtkbnsstno, jdbcType = VARCHAR} AND SYKM2.RCRDKBN = #{sysRcrdKbn, jdbcType = VARCHAR} AND SYKM2.SETTEICD = JHTT.DATSKSMOTOKBN ) LEFT OUTER JOIN S02M006T SYKM3 ON ( SYKM3.APKIHONCD = #{sysApkihoncd, jdbcType = VARCHAR} AND SYKM3.SHOPCD = #{sysShopcd, jdbcType = VARCHAR} AND SYKM3.SETTEINO = #{acptkbnsstno, jdbcType = VARCHAR} AND SYKM3.RCRDKBN = #{sysRcrdKbn, jdbcType = VARCHAR} AND SYKM3.SETTEICD = JHTT.ACPTKBN ) LEFT OUTER JOIN S02M006T SYKM4 ON ( SYKM4.APKIHONCD = #{sysApkihoncd, jdbcType = VARCHAR} AND SYKM4.SHOPCD = #{sysShopcd, jdbcType = VARCHAR} AND SYKM4.SETTEINO = #{acptkbndtlsstno, jdbcType = VARCHAR} AND SYKM4.RCRDKBN = #{sysRcrdKbn, jdbcType = VARCHAR} AND SYKM4.SETTEICD = JHTT.ACPTKBNSHS ) LEFT OUTER JOIN S02M006T SYKM5 ON ( SYKM5.APKIHONCD = #{sysApkihoncd, jdbcType = VARCHAR} AND SYKM5.SHOPCD = #{sysShopcd, jdbcType = VARCHAR} AND SYKM5.SETTEINO = #{nhsk1sstno, jdbcType = VARCHAR} AND SYKM5.RCRDKBN = #{sysRcrdKbn, jdbcType = VARCHAR} AND SYKM5.SETTEICD = TKSM.NOHINSAKIJOHON1 ) LEFT OUTER JOIN S02M006T SYKM6 ON ( SYKM6.APKIHONCD = #{sysApkihoncd, jdbcType = VARCHAR} AND SYKM6.SHOPCD = #{sysShopcd, jdbcType = VARCHAR} AND SYKM6.SETTEINO = #{nhsk2sstno, jdbcType = VARCHAR} AND SYKM6.RCRDKBN = #{sysRcrdKbn, jdbcType = VARCHAR} AND SYKM6.SETTEICD = TKSM.NOHINSAKIJOHON2 ) LEFT OUTER JOIN S02M006T SYKM7 ON ( SYKM7.APKIHONCD = #{sysApkihoncd, jdbcType = VARCHAR} AND SYKM7.SHOPCD = #{sysShopcd, jdbcType = VARCHAR} AND SYKM7.SETTEINO = #{dlvrykbjknsstno, jdbcType = VARCHAR} AND SYKM7.RCRDKBN = #{sysRcrdKbn, jdbcType = VARCHAR} AND SYKM7.SETTEICD = JHTT.DLVRYKIBOJIKANKBN ) WHERE JHTT.APKIHONCD = #{apkihoncd, jdbcType = VARCHAR} AND JHTT.SHOPCD = #{shopcd, jdbcType = VARCHAR}
AND JHTT.YUKOKBN = '1' AND JHTT.TOKUISAKICD = #{tokuisakicd, jdbcType = VARCHAR} AND JHTT.DNPYSTS = '01'
AND JHTT.ACPTDNPYNO = #{acptdnpyno, jdbcType = VARCHAR} AND JHTT.EDANO = #{edano, jdbcType = VARCHAR}
ORDER BY JHTT.ACPTDNPYNO DESC , JHTT.EDANO DESC
